DATA_VERSION_TTL = 604800  # 7 days, same as other Redis keys

def _bump_data_version(user_id):
    """Bump the data version for a user (called after any mutation)."""
    if not _redis_client or not app.config.get('REDIS_OK'):
        return
    try:
        import time
        version = str(int(time.time() * 1000))  # millisecond timestamp
        _redis_client.setex(f"data_version:{user_id}", DATA_VERSION_TTL, version)
    except Exception:
        pass

def _get_data_version(user_id):
    """Get the current data version for a user."""
    if not _redis_client or not app.config.get('REDIS_OK'):
        return '0'
    try:
        v = _redis_client.get(f"data_version:{user_id}")
        return v or '0'
    except Exception:
        return '0'

@app.route('/api/data-version', methods=['GET'])
@login_required
def api_data_version():
    """Return the current data version for the logged-in user."""
    version = _get_data_version(current_user.id)
    return jsonify({'version': version})


def _email_delivery_verified():
    """
    Whether this instance has a verified sending address.

    Registered as a lazy Jinja global rather than a context processor on
    purpose: it costs two queries, and only the login and reset-password pages
    need it. A context processor would charge every dashboard render for
    something almost no page asks about.

    Never raises. A template helper must not be able to take the login page
    down - if this cannot be determined, the answer is "no", which hides the
    link rather than offering one that leads nowhere.
    """
    try:
        from instance_settings import is_verified
        return is_verified()
    except Exception as e:
        log_error(app.logger, 'SETTINGS', f'Could not determine email verification state: {e}')
        return False


app.jinja_env.globals['email_delivery_verified'] = _email_delivery_verified


def _fontawesome_pro_available():
    """
    True when a Font Awesome Pro build is present in static/fontawesome/.

    Pro is commercial, per-seat software, so it is not distributed with this
    application - see THIRD-PARTY-NOTICES.md. An operator who owns a licence
    drops their build into that directory and it is used automatically;
    otherwise the bundled Free build plus static/css/fa-pro-fallback.css takes
    over, which is what keeps every icon rendering either way.

    Checked on every render rather than cached: one os.path.exists is cheaper
    than the confusion of dropping a Pro build in and finding it ignored until
    somebody restarts Apache.

    Fails to FREE. If this cannot be determined the fallback still renders every
    icon, whereas guessing Pro would render blank boxes for the 36 glyphs that
    only exist there.
    """
    try:
        return os.path.exists(os.path.join(
            app.root_path, 'static', 'fontawesome', 'css', 'all.min.css'))
    except Exception as e:
        log_error(app.logger, 'CONFIG', f'Could not check for a Font Awesome Pro build: {e}')
        return False


app.jinja_env.globals['fontawesome_pro_available'] = _fontawesome_pro_available


@app.context_processor
def inject_unread_notifications():
    """Inject unread notification count and user info into all templates for the nav"""
    unread_count = 0
    first_name = ''
    last_name = ''
    
    if current_user.is_authenticated:
        try:
            # Get unread notification count (Redis-first)
            notifications_key = f"notifications:v1:{current_user.id}"
            if app.config.get('REDIS_OK'):
                try:
                    cached = _redis_client.get(notifications_key)
                    if cached:
                        notifications = json.loads(cached)
                        unread_count = sum(1 for n in notifications if not n.get('is_read'))
                except Exception:
                    pass
            
            # Fallback to MySQL if Redis didn't have data
            if unread_count == 0 and app.config.get('REDIS_OK'):
                # Check if we got 0 from Redis or just didn't find data
                try:
                    cached = _redis_client.get(notifications_key)
                    if not cached or cached == b'[]':
                        # No Redis data, fall back to MySQL
                        with get_db_pool().get_connection() as conn:
                            cursor = conn.cursor()
                            cursor.execute("""
                                SELECT COUNT(*) FROM notifications
                                WHERE user_id = %s AND is_read = 0
                            """, (current_user.id,))
                            result = cursor.fetchone()
                            if result:
                                unread_count = result[0]
                            cursor.close()
                except Exception:
                    pass
            elif not app.config.get('REDIS_OK'):
                # Redis not available, use MySQL
                with get_db_pool().get_connection() as conn:
                    cursor = conn.cursor()
                    cursor.execute("""
                        SELECT COUNT(*) FROM notifications
                        WHERE user_id = %s AND is_read = 0
                    """, (current_user.id,))
                    result = cursor.fetchone()
                    if result:
                        unread_count = result[0]
                    cursor.close()
            
            # Get user's first and last name (try Redis first)
            user_data = None
            redis_key = f"users:v1:{current_user.id}"
            if app.config.get('REDIS_OK'):
                try:
                    cached = _redis_client.get(redis_key)
                    if cached:
                        user_data = json.loads(cached)
                except Exception:
                    pass
            
            # Fallback to MySQL if not in Redis
            if not user_data:
                with get_db_pool().get_connection() as conn:
                    cursor = conn.cursor()
                    cursor.execute("""
                        SELECT first_name, last_name
                        FROM users
                        WHERE id = %s
                    """, (current_user.id,))
                    user_result = cursor.fetchone()
                    if user_result:
                        first_name = user_result[0] or ''
                        last_name = user_result[1] or ''
                    cursor.close()
            else:
                first_name = user_data.get('first_name', '') or ''
                last_name = user_data.get('last_name', '') or ''
                
        except Exception as e:
            log_error(app.logger, 'NOTIFICATION', f"Error in context processor: {e}")
    
    # Check if user has any the bank provider-connected accounts (for nav visibility)
    has_bank_accounts = False
    if current_user.is_authenticated:
        try:
            linked_accounts_key = f"linked_accounts:v1:{current_user.id}"
            if app.config.get('REDIS_OK'):
                cached = _redis_client.get(linked_accounts_key)
                if cached:
                    accounts = json.loads(cached)
                    has_bank_accounts = len(accounts) > 0
            if not has_bank_accounts:
                # Fallback: check credit_accounts for is_linked=1 or linked_accounts table
                credit_accounts = _get_credit_accounts_from_redis(current_user.id)
                if credit_accounts:
                    has_bank_accounts = any(int(ca.get('is_linked', 0)) == 1 for ca in credit_accounts)
        except Exception:
            pass

    # Check if user has any linked connections (for nav link text)
    has_bank_connections = False
    if current_user.is_authenticated:
        try:
            linked_connections_key = f"linked_connections:v1:{current_user.id}"
            if app.config.get('REDIS_OK'):
                cached = _redis_client.get(linked_connections_key)
                if cached:
                    conns = json.loads(cached)
                    has_bank_connections = len(conns) > 0
            if not has_bank_connections:
                # Fallback to MySQL
                with get_db_pool().get_connection() as conn:
                    cursor = conn.cursor()
                    cursor.execute(
                        "SELECT COUNT(*) FROM linked_connections WHERE user_id = %s",
                        (current_user.id,)
                    )
                    result = cursor.fetchone()
                    has_bank_connections = result and result[0] > 0
                    cursor.close()
        except Exception:
            pass

    # Count pending transactions (pending=1 or auto_confirmed=1) for nav badge
    pending_transactions_count = 0
    if current_user.is_authenticated and has_bank_accounts:
        try:
            for table_name in ('income_entries', 'expense_entries', 'c_expense_entries'):
                entries = _get_entries_from_redis(table_name, current_user.id) or []
                for entry in entries:
                    if entry.get('pending') == 1 or entry.get('auto_confirmed') == 1:
                        pending_transactions_count += 1
        except Exception:
            pass

    # Get data version for cross-tab sync
    data_version = '0'
    if current_user.is_authenticated:
        data_version = _get_data_version(current_user.id)

    return dict(
        unread_notifications_count=unread_count,
        nav_first_name=first_name,
        nav_last_name=last_name,
        has_bank_accounts=has_bank_accounts,
        has_bank_connections=has_bank_connections,
        pending_transactions_count=pending_transactions_count,
        data_version=data_version
    )

