# ============================================================
# Recurring Mismatch Detection Helper
# ============================================================

# the enrichment provider periodicity → app cadence mapping
_ENRICHMENT_CADENCE_MAP = {
    'daily':        (1, 'days'),
    'weekly':       (1, 'weeks'),
    'bi-weekly':    (2, 'weeks'),
    'bi_weekly':    (2, 'weeks'),
    'monthly':      (1, 'months'),
    'bi-monthly':   (2, 'months'),
    'bi_monthly':   (2, 'months'),
    'quarterly':    (3, 'months'),
    'semi-yearly':  (6, 'months'),
    'semi_yearly':  (6, 'months'),
    'yearly':       (1, 'years'),
}

# Fuzzy match ranges for 'other' periodicity (periodicity_days → cadence)
_FUZZY_CADENCE_RANGES = [
    (1, 1, 1, 'days'),        # 1 day
    (5, 9, 1, 'weeks'),       # ~7 days
    (11, 17, 2, 'weeks'),     # ~14 days
    (28, 33, 1, 'months'),    # ~30 days
    (57, 63, 2, 'months'),    # ~60 days
    (87, 93, 3, 'months'),    # ~90 days
    (177, 183, 6, 'months'),  # ~180 days
    (362, 368, 1, 'years'),   # ~365 days
]

_DAY_NAMES = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']


def _detect_recurring_mismatch(transaction_record, entry_type, category_id, user_id):
    """
    Check if a confirmed transaction's amount/cadence differs from the recurring entry.
    Creates/updates/deletes mismatch records as needed.
    
    Args:
        transaction_record: Dict from linked_transactions (must have amount, enrichment_recurrence, 
                           enrichment_periodicity, enrichment_periodicity_days, date, transaction_id)
        entry_type: 'income', 'expense', or 'c_expense'
        category_id: The confirmed category ID
        user_id: User ID
    """
    enrichment_recurrence = (transaction_record.get('enrichment_recurrence') or '').lower().strip()
    if enrichment_recurrence not in ('recurring', 'subscription'):
        return
    
    recurring_table_map = {
        'income': 'recurring_income',
        'expense': 'recurring_expense',
        'c_expense': 'recurring_c_expense'
    }
    recurring_table = recurring_table_map.get(entry_type)
    if not recurring_table:
        return
    
    # Get ALL recurring entries for this category
    try:
        redis_key = f"{recurring_table}:v1:{user_id}"
        cached = _redis_client.get(redis_key) if app.config.get('REDIS_OK') else None
        if not cached:
            return
        all_recurring = json.loads(cached)
    except Exception as e:
        log_error(app.logger, 'MISMATCH', f"Error reading recurring entries: {e}", user_id=user_id)
        return
    
    # Filter to wage_bill=1 entries for this category
    wage_bill_entries = [
        r for r in all_recurring
        if int(r.get('category_id', 0)) == int(category_id) and int(r.get('wage_bill', 0)) == 1
    ]
    
    if not wage_bill_entries:
        _detect_recurring_suggestion(transaction_record, entry_type, category_id, user_id, all_recurring, recurring_table)
        return
    
    txn_amount = float(transaction_record.get('amount', 0))
    enrichment_periodicity = (transaction_record.get('enrichment_periodicity') or '').lower().strip().replace('_', '-')
    enrichment_periodicity_days = transaction_record.get('enrichment_periodicity_days')
    txn_date_str = transaction_record.get('date')
    transaction_id = transaction_record.get('transaction_id')
    
    # Parse transaction date for day-of-week / day-of-month inference
    txn_weekday_name = None
    txn_day_of_month = None
    if txn_date_str:
        try:
            if isinstance(txn_date_str, str):
                txn_date = datetime.strptime(txn_date_str[:10], '%Y-%m-%d')
            else:
                txn_date = txn_date_str
            txn_weekday_name = _DAY_NAMES[txn_date.weekday()]  # 0=monday
            txn_day_of_month = txn_date.day
        except Exception:
            pass
    
    # Determine detected cadence from enrichment
    detected_interval = None
    detected_unit = None
    
    if enrichment_periodicity and enrichment_periodicity != 'other':
        mapped = _ENRICHMENT_CADENCE_MAP.get(enrichment_periodicity)
        if mapped:
            detected_interval, detected_unit = mapped
    elif enrichment_periodicity == 'other' and enrichment_periodicity_days:
        # Fuzzy match using ±3 day tolerance
        try:
            days = float(enrichment_periodicity_days)
            for low, high, interval, unit in _FUZZY_CADENCE_RANGES:
                if low <= days <= high:
                    detected_interval, detected_unit = interval, unit
                    break
        except (ValueError, TypeError):
            pass
    
    for rec_entry in wage_bill_entries:
        recurring_id = rec_entry.get('id')
        rec_amount = float(rec_entry.get('amount', 0))
        rec_interval = int(rec_entry.get('cadence_interval', 0))
        rec_unit = (rec_entry.get('cadence_unit') or '').lower().strip()
        rec_weekdays = (rec_entry.get('weekdays') or '').lower().strip()
        rec_monthly_days = (rec_entry.get('monthly_days') or '').strip()
        
        has_mismatch = False
        
        # Amount comparison: >$1 or >2%, whichever is greater
        amount_diff = abs(txn_amount - rec_amount)
        threshold = max(1.0, rec_amount * 0.02)
        if amount_diff > threshold:
            has_mismatch = True
            log_info(app.logger, 'MISMATCH', f"Amount mismatch: txn={txn_amount}, rec={rec_amount}, diff={amount_diff:.2f}",
                     recurring_id=recurring_id, user_id=user_id)
        
        # Cadence comparison (only if we have detected cadence)
        if detected_interval is not None and detected_unit is not None:
            # Compare interval + unit
            if detected_interval != rec_interval or detected_unit != rec_unit:
                has_mismatch = True
                log_info(app.logger, 'MISMATCH', f"Cadence mismatch: detected={detected_interval}/{detected_unit}, rec={rec_interval}/{rec_unit}",
                         recurring_id=recurring_id, user_id=user_id)
            else:
                # Cadence matches — check day-of-week/month
                if detected_unit == 'weeks' and txn_weekday_name and rec_weekdays:
                    rec_weekday_list = [w.strip() for w in rec_weekdays.split(',') if w.strip()]
                    if txn_weekday_name not in rec_weekday_list:
                        has_mismatch = True
                        log_info(app.logger, 'MISMATCH', f"Weekday mismatch: txn={txn_weekday_name}, rec={rec_weekdays}",
                                 recurring_id=recurring_id, user_id=user_id)
                
                if detected_unit == 'months' and txn_day_of_month and rec_monthly_days:
                    rec_days_list = [int(d.strip()) for d in rec_monthly_days.split(',') if d.strip()]
                    if txn_day_of_month not in rec_days_list:
                        has_mismatch = True
                        log_info(app.logger, 'MISMATCH', f"Monthly day mismatch: txn day={txn_day_of_month}, rec={rec_monthly_days}",
                                 recurring_id=recurring_id, user_id=user_id)
        
        if has_mismatch:
            upsert_recurring_mismatch({
                'recurring_table': recurring_table,
                'recurring_id': recurring_id,
                'category_id': category_id,
                'transaction_id': transaction_id,
            }, user_id=user_id)
        else:
            # Self-healing: no mismatch, remove any existing record
            delete_recurring_mismatch(recurring_table, recurring_id, user_id=user_id)


def _detect_recurring_suggestion(transaction_record, entry_type, category_id, user_id, all_recurring, recurring_table):
    """
    Check if a confirmed transaction should generate a "suggested recurring" entry.
    Called when a transaction is confirmed to a non-recurring category (no wage_bill=1 entries).
    
    Qualification: category is_recurring=0, no recurring entries at all for this category,
    transaction has enrichment recurring flag + non-NULL periodicity, category not hidden.
    
    Args:
        transaction_record: Dict from linked_transactions
        entry_type: 'income', 'expense', or 'c_expense'
        category_id: The confirmed category ID
        user_id: User ID
        all_recurring: Already-fetched recurring entries list (avoids duplicate Redis read)
        recurring_table: 'recurring_income', 'recurring_expense', or 'recurring_c_expense'
    """
    try:
        # Check if ANY recurring entry exists for this category (not just wage_bill=1)
        any_recurring_for_cat = any(
            int(r.get('category_id', 0)) == int(category_id) for r in all_recurring
        )
        if any_recurring_for_cat:
            return

        # Check enrichment_periodicity is not NULL
        enrichment_periodicity = (transaction_record.get('enrichment_periodicity') or '').lower().strip().replace('_', '-')
        if not enrichment_periodicity:
            return

        # Look up the category to check is_recurring and hidden
        cat_table_map = {
            'income': 'income_categories',
            'expense': 'expense_categories',
            'c_expense': 'c_expense_categories'
        }
        cat_table = cat_table_map.get(entry_type)
        if not cat_table:
            return

        categories = _get_categories_from_redis(cat_table, user_id)
        if not categories:
            return

        category = next((c for c in categories if str(c.get('id')) == str(category_id)), None)
        if not category:
            return

        if int(category.get('is_recurring', 0)) == 1:
            return
        if int(category.get('hidden', 0)) == 1:
            return

        # Compute detected cadence
        detected_interval = None
        detected_unit = None

        if enrichment_periodicity and enrichment_periodicity != 'other':
            mapped = _ENRICHMENT_CADENCE_MAP.get(enrichment_periodicity)
            if mapped:
                detected_interval, detected_unit = mapped
        elif enrichment_periodicity == 'other':
            enrichment_periodicity_days = transaction_record.get('enrichment_periodicity_days')
            if enrichment_periodicity_days:
                try:
                    days = float(enrichment_periodicity_days)
                    for low, high, interval, unit in _FUZZY_CADENCE_RANGES:
                        if low <= days <= high:
                            detected_interval, detected_unit = interval, unit
                            break
                except (ValueError, TypeError):
                    pass

        # If we couldn't determine cadence, skip
        if detected_interval is None or detected_unit is None:
            return

        # Infer weekday / day-of-month from transaction date
        detected_weekday = None
        detected_monthly_day = None
        txn_date_str = transaction_record.get('date')
        if txn_date_str:
            try:
                if isinstance(txn_date_str, str):
                    txn_date = datetime.strptime(txn_date_str[:10], '%Y-%m-%d')
                else:
                    txn_date = txn_date_str
                if detected_unit == 'weeks':
                    detected_weekday = _DAY_NAMES[txn_date.weekday()]
                if detected_unit == 'months':
                    detected_monthly_day = txn_date.day
            except Exception:
                pass

        suggestion_type_map = {
            'income': 'recurring_income',
            'expense': 'recurring_expense',
            'c_expense': 'recurring_c_expense'
        }
        suggestion_type = suggestion_type_map.get(entry_type)

        txn_amount = abs(float(transaction_record.get('amount', 0)))
        transaction_id = transaction_record.get('transaction_id')

        upsert_recurring_suggestion({
            'suggestion_type': suggestion_type,
            'category_id': int(category_id),
            'transaction_id': transaction_id,
            'detected_amount': txn_amount,
            'detected_cadence_interval': detected_interval,
            'detected_cadence_unit': detected_unit,
            'detected_weekday': detected_weekday,
            'detected_monthly_day': detected_monthly_day,
        }, user_id=user_id)

        log_info(app.logger, 'SUGGEST_REC', 'Recurring suggestion created',
                 category_id=category_id, suggestion_type=suggestion_type,
                 amount=txn_amount, cadence=f"{detected_interval}/{detected_unit}",
                 user_id=user_id)

    except Exception as e:
        log_exception(app.logger, 'SUGGEST_REC', f"Error detecting recurring suggestion: {e}",
                      category_id=category_id, user_id=user_id)


def _filter_pending_deletions(table_name, user_id, entries):
    """
    Filter out entries that are pending deletion (deleted from Redis but not yet flushed to MySQL).
    This prevents MySQL fallback from resurrecting deleted entries.
    
    Args:
        table_name: Table name
        user_id: User ID
        entries: List of entries from MySQL
        
    Returns:
        Filtered list of entries
    """
    if not app.config.get('REDIS_OK') or not entries:
        return entries
    
    try:
        pending_key = f"pending_deletes:{table_name}:{user_id}"
        pending_deletes = _redis_client.smembers(pending_key)
        
        if not pending_deletes:
            return entries
        
        # Convert to set of integers for fast lookup
        pending_delete_ids = {int(id_str) for id_str in pending_deletes}
        
        # Filter out entries with IDs in the pending deletion set
        filtered = [entry for entry in entries if entry.get('id') not in pending_delete_ids]
        
        if len(filtered) < len(entries):
            pass
        
        return filtered
        
    except Exception as e:
        pass
        return entries

def _set_entries_to_redis(table_name, user_id, data):
    """
    Set entries to Redis and mark dirty for flush.
    
    Args:
        table_name: 'income_entries', 'expense_entries', or 'c_expense_entries'
        user_id: User ID
        data: List of entry records
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        # Serialize data
        serializable_data = []
        for row in data:
            row_copy = row.copy()
            if 'date' in row_copy and isinstance(row_copy['date'], date):
                row_copy['date'] = row_copy['date'].isoformat()
            for k, v in row_copy.items():
                if isinstance(v, Decimal):
                    row_copy[k] = float(v)
            serializable_data.append(row_copy)
        
        _redis_client.setex(redis_key, PERSISTENT_CACHE_TTL, json.dumps(serializable_data))
        # Mark table as dirty for flush
        dirty_key = f"dirty_tables:{user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
    except Exception as e:
        pass

def _update_entry_in_redis(table_name, user_id, category_id, entry_date, amount, processed=0, entry_id=None, bud_item_id=None, is_bucket=False, original_amount=None, recurring_id=None, is_auto_adjustment=False, match_entry_id=None):
    """
    Update or insert a single entry in Redis cache.
    
    Args:
        table_name: 'income_entries', 'expense_entries', or 'c_expense_entries'
        user_id: User ID
        category_id: Category ID
        entry_date: Entry date (date object or string)
        amount: Entry amount
        processed: Processed flag (0 or 1)
        entry_id: Existing entry ID (if updating) or None (will generate)
        bud_item_id: Optional bud_item_id for expense entries
        is_bucket: Whether this is a bucket entry from recurring
        original_amount: Original amount for bucket tracking
        recurring_id: Optional recurring entry ID
        is_auto_adjustment: Whether this is a nightly auto-adjustment entry
        match_entry_id: When provided, match existing entry by this ID instead of category+date+is_bucket
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        # Get current entries from Redis
        entries = _get_entries_from_redis(table_name, user_id)
        
        # If not in Redis, load from MySQL first
        if entries is None:
            entries = []
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                if table_name == 'income_entries':
                    cursor.execute("""
                        SELECT ie.* FROM income_entries ie
                        JOIN income_categories ic ON ie.category_id = ic.id
                        WHERE ic.user_id = %s
                    """, (user_id,))
                elif table_name == 'expense_entries':
                    cursor.execute("""
                        SELECT ee.* FROM expense_entries ee
                        JOIN expense_categories ec ON ee.category_id = ec.id
                        WHERE ec.user_id = %s
                    """, (user_id,))
                elif table_name == 'c_expense_entries':
                    cursor.execute("""
                        SELECT cee.* FROM c_expense_entries cee
                        JOIN c_expense_categories cec ON cee.category_id = cec.id
                        JOIN credit_accounts ca ON cec.account_id = ca.id
                        WHERE ca.user_id = %s
                    """, (user_id,))
                entries = list(cursor.fetchall())
                cursor.close()
            
            # Filter out any entries pending deletion
            entries = _filter_pending_deletions(table_name, user_id, entries)
        
        # Convert entry_date to string for comparison
        if isinstance(entry_date, date):
            entry_date_str = entry_date.isoformat()
        else:
            entry_date_str = entry_date
        
        # Find existing entry
        # When match_entry_id is provided, match by ID for precise targeting (e.g., dashboard_d edits)
        # Otherwise, match by category_id + date + is_bucket (legacy behavior)
        found = False
        for entry in entries:
            if match_entry_id is not None:
                # Match by specific entry ID
                if entry.get('id') is not None and int(entry.get('id')) == int(match_entry_id):
                    entry['amount'] = float(amount)
                    entry['processed'] = int(processed)
                    if bud_item_id is not None:
                        entry['bud_item_id'] = int(bud_item_id)
                    if original_amount is not None:
                        entry['original_amount'] = float(original_amount)
                    found = True
                    break
            else:
                # Legacy: match by category_id + date + is_bucket
                if (int(entry.get('category_id', 0)) == int(category_id) and 
                    entry.get('date') == entry_date_str and
                    bool(entry.get('is_bucket', 0)) == bool(is_bucket)):
                    # Update existing entry
                    entry['amount'] = float(amount)
                    entry['processed'] = int(processed)
                    if bud_item_id is not None:
                        entry['bud_item_id'] = int(bud_item_id)
                    found = True
                    break
        
        if not found:
            # Create new entry
            # Generate a NEGATIVE temp ID to avoid collision with MySQL IDs
            # The flush worker will replace this with the real auto-increment ID
            existing_ids = [e.get('id', 0) for e in entries if e.get('id')]
            min_id = min(existing_ids) if existing_ids else 0
            temp_id = min(min_id, 0) - 1  # Always negative: -1, -2, -3, etc.
            new_entry = {
                'id': entry_id or temp_id,
                'category_id': int(category_id),
                'date': entry_date_str,
                'amount': float(amount),
                'recurring_id': int(recurring_id) if recurring_id is not None else None,
                'processed': int(processed),
                'is_bucket': 1 if is_bucket else 0,
                'is_auto_adjustment': 1 if is_auto_adjustment else 0
            }
            if original_amount is not None:
                new_entry['original_amount'] = float(original_amount)
            if table_name in ['expense_entries', 'c_expense_entries']:
                new_entry['bud_item_id'] = int(bud_item_id) if bud_item_id is not None else None
            entries.append(new_entry)
        
        # Write back to Redis
        _set_entries_to_redis(table_name, user_id, entries)
        
    except Exception as e:
        pass


def _create_bucket_entry_and_record(table_name, user_id, category_id, entry_date, amount, recurring_id, account_id=None):
    """
    Helper to create both a bucket entry in Redis AND a bucket record.
    
    Args:
        table_name: 'income_entries', 'expense_entries', or 'c_expense_entries'
        user_id: User ID
        category_id: Category ID
        entry_date: Date for the bucket
        amount: Bucket amount
        recurring_id: Recurring entry ID
        account_id: Account ID (required for c_expense_entries)
    """
    
    # Create bucket entry in Redis
    _update_entry_in_redis(table_name, user_id, category_id, entry_date, float(amount),
                          processed=0, entry_id=None, is_bucket=True, 
                          original_amount=float(amount), recurring_id=recurring_id)
    
    
    # Create bucket record
    from recurring_bucket_manager import create_bucket_record
    bucket_id = create_bucket_record(table_name, user_id, category_id, entry_date, float(amount), account_id=account_id)
    

def _delete_entry_in_redis(table_name, user_id, category_id, start_date, end_date, specific_entry_id=None):
    """
    Delete entries in Redis cache for a date range, or a specific entry by ID.
    
    Args:
        table_name: 'income_entries', 'expense_entries', or 'c_expense_entries'
        user_id: User ID
        category_id: Category ID
        start_date: Start date (inclusive)
        end_date: End date (inclusive)
        specific_entry_id: When provided, delete only this specific entry (ignores date range matching)
    """
    if not app.config.get('REDIS_OK'):
        return
    
    # Ensure category_id is an integer
    category_id = int(category_id)
    
    try:
        # Get current entries from Redis
        entries = _get_entries_from_redis(table_name, user_id)
        
        # If not in Redis, load from MySQL first
        if entries is None:
            entries = []
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                if table_name == 'income_entries':
                    cursor.execute("""
                        SELECT ie.* FROM income_entries ie
                        JOIN income_categories ic ON ie.category_id = ic.id
                        WHERE ic.user_id = %s
                    """, (user_id,))
                elif table_name == 'expense_entries':
                    cursor.execute("""
                        SELECT ee.* FROM expense_entries ee
                        JOIN expense_categories ec ON ee.category_id = ec.id
                        WHERE ec.user_id = %s
                    """, (user_id,))
                elif table_name == 'c_expense_entries':
                    cursor.execute("""
                        SELECT cee.* FROM c_expense_entries cee
                        JOIN c_expense_categories cec ON cee.category_id = cec.id
                        JOIN credit_accounts ca ON cec.account_id = ca.id
                        WHERE ca.user_id = %s
                    """, (user_id,))
                entries = list(cursor.fetchall())
                cursor.close()
            
            # Filter out any entries pending deletion (in case cache was cleared)
            entries = _filter_pending_deletions(table_name, user_id, entries)
        
        # Convert dates to strings for comparison
        if isinstance(start_date, date):
            start_date_str = start_date.isoformat()
        else:
            start_date_str = start_date
        if isinstance(end_date, date):
            end_date_str = end_date.isoformat()
        else:
            end_date_str = end_date
        
        # Check if this category is recurring (to restore bucket amounts)
        category_is_recurring = False
        recurring_info = None
        
        # For temp IDs (negative), check Redis first
        if category_id < 0:
            pass
            
            if table_name == 'income_entries':
                recurring_table = 'recurring_income'
                category_table = 'income_categories'
            elif table_name == 'expense_entries':
                recurring_table = 'recurring_expense'
                category_table = 'expense_categories'
            elif table_name == 'c_expense_entries':
                recurring_table = 'recurring_c_expense'
                category_table = 'c_expense_categories'
            
            # Check if category is recurring from Redis
            cats = _get_categories_from_redis(category_table, user_id)
            if cats:
                cat = next((c for c in cats if c.get('id') == category_id), None)
                if cat and cat.get('is_recurring'):
                    category_is_recurring = True
                    # Get recurring info from Redis
                    recurring_info = _get_recurring_info_from_redis(recurring_table, user_id, category_id)
        else:
            # Real ID - check MySQL
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                
                if table_name == 'income_entries':
                    cursor.execute("""
                        SELECT ic.is_recurring, ri.*
                        FROM income_categories ic
                        LEFT JOIN recurring_income ri ON ic.id = ri.category_id
                        WHERE ic.id = %s
                    """, (category_id,))
                elif table_name == 'expense_entries':
                    cursor.execute("""
                        SELECT ec.is_recurring, re.*
                        FROM expense_categories ec
                        LEFT JOIN recurring_expense re ON ec.id = re.category_id
                        WHERE ec.id = %s
                    """, (category_id,))
                elif table_name == 'c_expense_entries':
                    cursor.execute("""
                        SELECT cec.is_recurring, rce.*
                        FROM c_expense_categories cec
                        LEFT JOIN recurring_c_expense rce ON cec.id = rce.category_id
                        WHERE cec.id = %s
                    """, (category_id,))
                
                result = cursor.fetchone()
                if result and result.get('is_recurring'):
                    category_is_recurring = True
                    recurring_info = result
                cursor.close()
        
        
        # Filter out entries in the date range for this category (or by specific ID)
        # Also track which entry IDs are being deleted
        deleted_ids = []
        deleted_entries_for_bucket_restore = []  # Track entries that need bucket restoration
        deleted_bucket_entries = []  # Track bucket entries that need their bucket record deleted
        filtered_entries = []
        for entry in entries:
            should_delete = False
            if specific_entry_id is not None:
                # Match by specific entry ID only
                should_delete = (entry.get('id') is not None and int(entry.get('id')) == int(specific_entry_id))
            else:
                # Legacy: match by category + date range
                entry_cat = int(entry.get('category_id', 0))
                entry_date = entry.get('date', '')
                should_delete = (entry_cat == int(category_id) and start_date_str <= entry_date <= end_date_str)
            
            if should_delete:
                # This entry is being deleted
                if 'id' in entry:
                    deleted_ids.append(entry['id'])
                    is_bucket_val = entry.get('is_bucket')
                    # NEW LOGIC (Feb 2026): Track ALL non-bucket entries for restoration
                    # The restore function will check if there's a bucket to restore to
                    # Check for is_bucket being 1, True, or "1"
                    if is_bucket_val in (1, True, "1"):
                        # PHASE 4 (Feb 2026): Track bucket entries - need to delete bucket record too
                        deleted_bucket_entries.append(entry)
                    else:
                        deleted_entries_for_bucket_restore.append(entry)
            else:
                # Keep this entry
                filtered_entries.append(entry)
        
        
        # Restore bucket amounts for deleted entries
        # NEW LOGIC (Feb 2026): Use simplified v2 function that finds NEXT bucket, not cadence-based
        updated_bucket_ids = set()  # Track which buckets were updated
        if deleted_entries_for_bucket_restore:
            from bucket_utils import restore_bucket_for_deleted_entry_v2, find_next_bucket_for_category
            
            for entry in deleted_entries_for_bucket_restore:
                try:
                    entry_amount = Decimal(str(entry.get('amount', 0)))
                    
                    # Find which bucket would be affected (the next bucket in category)
                    bucket = find_next_bucket_for_category(table_name, category_id, user_id)
                    
                    restored = restore_bucket_for_deleted_entry_v2(
                        table_name,
                        category_id,
                        entry_amount,
                        user_id
                    )
                    
                    if restored and bucket:
                        # Track that this bucket was updated so we can refresh entries
                        updated_bucket_ids.add(bucket.get('id'))
                    elif restored:
                        # Bucket was restored but couldn't find it
                        # Force a refresh by adding a dummy ID
                        updated_bucket_ids.add(-1)
                except Exception as e:
                    log_error(app.logger, 'DELETE_ENTRY', f"Error restoring bucket: {e}")
        
        # PHASE 4 (Feb 2026): Delete bucket records for deleted bucket entries
        if deleted_bucket_entries:
            from bucket_utils import delete_bucket_record_for_entry
            
            for entry in deleted_bucket_entries:
                try:
                    entry_date = entry.get('date', '')
                    delete_bucket_record_for_entry(
                        table_name,
                        category_id,
                        entry_date,
                        user_id
                    )
                    log_info(app.logger, 'DELETE_ENTRY', f"Deleted bucket record for category {category_id}, date {entry_date}")
                except Exception as e:
                    log_error(app.logger, 'DELETE_ENTRY', f"Error deleting bucket record: {e}")
        
        # If buckets were updated, refresh the filtered_entries list from Redis to get updated bucket amounts
        if updated_bucket_ids:
            pass
            refreshed_entries = _get_entries_from_redis(table_name, user_id)
            if refreshed_entries:
                # Rebuild filtered_entries with updated bucket amounts
                deleted_ids_set = set(deleted_ids)
                filtered_entries = [entry for entry in refreshed_entries if entry.get('id') not in deleted_ids_set]
        
        # Write filtered entries back to Redis
        _set_entries_to_redis(table_name, user_id, filtered_entries)
        
        # Track pending deletions to prevent MySQL fallback from resurrecting them
        if deleted_ids:
            pending_key = f"pending_deletes:{table_name}:{user_id}"
            _redis_client.sadd(pending_key, *deleted_ids)
            _redis_client.expire(pending_key, PERSISTENT_CACHE_TTL)  # Expire after flush would complete
        
    except Exception as e:
        pass

def _update_payment_entry_in_redis(user_id, account_id, entry_date, amount):
    """
    Update or insert a payment entry in Redis cache.
    
    Args:
        user_id: User ID
        account_id: Credit account ID
        entry_date: Payment date (date object or string)
        amount: Payment amount
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        table_name = 'c_payment_entries'
        # Get current entries from Redis
        entries = _get_entries_from_redis(table_name, user_id)
        
        # If not in Redis, load from MySQL first
        if entries is None:
            entries = []
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                cursor.execute("""
                    SELECT cpe.* FROM c_payment_entries cpe
                    JOIN credit_accounts ca ON cpe.account_id = ca.id
                    WHERE ca.user_id = %s
                """, (user_id,))
                entries = list(cursor.fetchall())
                cursor.close()
            
            # Filter out any entries pending deletion
            entries = _filter_pending_deletions(table_name, user_id, entries)
        
        # Convert entry_date to string for comparison
        if isinstance(entry_date, date):
            entry_date_str = entry_date.isoformat()
        else:
            entry_date_str = entry_date
        
        # Find existing entry
        found = False
        for entry in entries:
            if (int(entry.get('account_id', 0)) == int(account_id) and 
                entry.get('date') == entry_date_str):
                # Update existing entry
                entry['amount'] = float(amount)
                found = True
                break
        
        if not found:
            # Generate a new ID (use negative to avoid conflicts with MySQL IDs)
            max_id = max([abs(int(e.get('id', 0))) for e in entries], default=0)
            new_id = -(max_id + 1)
            
            # Add new entry
            entries.append({
                'id': new_id,
                'account_id': int(account_id),
                'date': entry_date_str,
                'amount': float(amount),
                'recurring_id': None,
                'processed': 0
            })
        
        # Save back to Redis
        _set_entries_to_redis(table_name, user_id, entries)
        
    except Exception as e:
        pass

def _delete_payment_entry_in_redis(user_id, account_id, start_date, end_date):
    """
    Delete payment entries from Redis cache by account and date range.
    
    Args:
        user_id: User ID
        account_id: Credit account ID
        start_date: Start date (inclusive)
        end_date: End date (inclusive)
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        table_name = 'c_payment_entries'
        # Get current entries from Redis
        entries = _get_entries_from_redis(table_name, user_id)
        
        # If not in Redis, load from MySQL first
        if entries is None:
            entries = []
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                cursor.execute("""
                    SELECT cpe.* FROM c_payment_entries cpe
                    JOIN credit_accounts ca ON cpe.account_id = ca.id
                    WHERE ca.user_id = %s
                """, (user_id,))
                entries = list(cursor.fetchall())
                cursor.close()
        
        # Convert dates to strings for comparison
        if isinstance(start_date, date):
            start_date_str = start_date.isoformat()
        else:
            start_date_str = start_date
            
        if isinstance(end_date, date):
            end_date_str = end_date.isoformat()
        else:
            end_date_str = end_date
        
        # Filter out entries to delete
        deleted_ids = []
        filtered_entries = []
        for entry in entries:
            entry_date_str = entry.get('date')
            if (int(entry.get('account_id', 0)) == int(account_id) and
                start_date_str <= entry_date_str <= end_date_str):
                # Mark for deletion
                entry_id = entry.get('id')
                if entry_id and int(entry_id) > 0:  # Only track positive IDs (from MySQL)
                    deleted_ids.append(str(entry_id))
            else:
                filtered_entries.append(entry)
        
        # Save filtered entries back to Redis
        _set_entries_to_redis(table_name, user_id, filtered_entries)
        
        # Track pending deletions to prevent MySQL fallback from resurrecting them
        if deleted_ids:
            pending_key = f"pending_deletes:{table_name}:{user_id}"
            _redis_client.sadd(pending_key, *deleted_ids)
            _redis_client.expire(pending_key, PERSISTENT_CACHE_TTL)
        
    except Exception as e:
        pass

def _get_payment_entries_from_redis(user_id):
    """
    Get payment entries from Redis.
    
    Args:
        user_id: User ID
        
    Returns:
        List of dicts or None if not in cache
    """
    if not app.config.get('REDIS_OK'):
        return None
    
    try:
        redis_key = f"c_payment_entries:v1:{user_id}"
        cached = _redis_client.get(redis_key)
        if cached:
            return json.loads(cached)
        return None
    except Exception as e:
        log_error(app.logger, 'REDIS', f"Error getting payment entries from Redis: {e}")
        return None

# Redis helper functions for recurring tables

def _get_recurring_from_redis(table_name, user_id):
    """
    Get recurring records from Redis.
    
    Args:
        table_name: 'recurring_income', 'recurring_expense', or 'recurring_c_expense'
        user_id: User ID
        
    Returns:
        List of dicts or None if not in cache
    """
    if not app.config.get('REDIS_OK'):
        return None
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        cached = _redis_client.get(redis_key)
        if cached:
            return json.loads(cached)
        return None
    except Exception as e:
        log_error(app.logger, 'RECURRING', f"Error getting {table_name} from Redis: {e}")
        return None

def _set_recurring_to_redis(table_name, user_id, data):
    """
    Set recurring records to Redis and mark dirty for flush.
    
    Args:
        table_name: 'recurring_income', 'recurring_expense', or 'recurring_c_expense'
        user_id: User ID
        data: List of recurring records
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        _redis_client.setex(
            redis_key,
            PERSISTENT_CACHE_TTL,
            json.dumps(data, cls=DecimalEncoder)
        )
        
        # Mark table as dirty for flush worker
        dirty_key = f"dirty_tables:{user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
    except Exception as e:
        log_error(app.logger, 'RECURRING', f"Error setting {table_name} to Redis: {e}")

def _update_recurring_in_redis(table_name, user_id, recurring_data):
    """
    Update or insert a single recurring record in Redis cache.
    
    Args:
        table_name: 'recurring_income', 'recurring_expense', or 'recurring_c_expense'
        user_id: User ID
        recurring_data: Dict with recurring record data (must include 'id' for update or None for insert)
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data
        cached = _redis_client.get(redis_key)
        if cached:
            rows = json.loads(cached)
        else:
            rows = []
        
        recurring_id = recurring_data.get('id')
        
        if recurring_id:
            # Update existing record
            found = False
            for i, row in enumerate(rows):
                if int(row.get('id')) == int(recurring_id):
                    # Preserve category_name if not provided in update
                    if 'category_name' not in recurring_data and 'category_name' in row:
                        recurring_data['category_name'] = row['category_name']
                    rows[i] = recurring_data
                    found = True
                    break
            
            if not found:
                # Record not in cache, add it
                rows.append(recurring_data)
        else:
            # New record - generate a temporary negative ID (will be replaced by MySQL on flush)
            temp_id = -int(time.time() * 1000000)  # Use negative timestamp to avoid collisions
            recurring_data['id'] = temp_id
            rows.append(recurring_data)
        
        # Save back to Redis
        _redis_client.setex(
            redis_key,
            PERSISTENT_CACHE_TTL,
            json.dumps(rows, cls=DecimalEncoder)
        )
        
        # Mark as dirty
        dirty_key = f"dirty_tables:{user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        
    except Exception as e:
        log_error(app.logger, 'RECURRING', f"Error updating {table_name} in Redis: {e}")

def _delete_recurring_in_redis(table_name, user_id, recurring_id):
    """
    Delete a recurring record from Redis cache.
    
    Args:
        table_name: 'recurring_income', 'recurring_expense', or 'recurring_c_expense'
        user_id: User ID
        recurring_id: ID of the recurring record to delete
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data
        cached = _redis_client.get(redis_key)
        if cached:
            rows = json.loads(cached)
            # Filter out the deleted record (compare as int to handle both int and str IDs)
            recurring_id_int = int(recurring_id)
            rows = [row for row in rows if int(row.get('id')) != recurring_id_int]
            
            # Save back to Redis
            _redis_client.setex(
                redis_key,
                PERSISTENT_CACHE_TTL,
                json.dumps(rows, cls=DecimalEncoder)
            )
        
        # Track pending deletion for flush worker (only for real MySQL IDs, not temp negative IDs)
        recurring_id_int = int(recurring_id)
        if recurring_id_int > 0:
            pending_key = f"pending_deletes:{table_name}:{user_id}"
            _redis_client.sadd(pending_key, str(recurring_id))
            _redis_client.expire(pending_key, PERSISTENT_CACHE_TTL)
        else:
            pass
        
        # Mark as dirty
        dirty_key = f"dirty_tables:{user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
    except Exception as e:
        log_error(app.logger, 'RECURRING', f"Error deleting {table_name} in Redis: {e}")

def _delete_category_in_redis(table_name, user_id, category_id):
    """
    Delete a category record from Redis cache and all associated entries and buckets.
    
    Args:
        table_name: 'income_categories', 'expense_categories', or 'c_expense_categories'
        user_id: User ID (or account_id for c_expense_categories)
        category_id: ID of the category to delete
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        category_id_int = int(category_id)
        
        # Determine table names for related entries and buckets
        # All tables now use user_id as the key
        if table_name == 'income_categories':
            entries_table = 'income_entries'
            buckets_table = 'recurring_income_buckets'
        elif table_name == 'expense_categories':
            entries_table = 'expense_entries'
            buckets_table = 'recurring_expense_buckets'
        elif table_name == 'c_expense_categories':
            entries_table = 'c_expense_entries'
            buckets_table = 'recurring_c_expense_buckets'
        else:
            entries_table = None
            buckets_table = None
        
        # user_id is now always the actual user_id
        pending_user_id = user_id
        
        # 1. Delete all entries for this category
        if entries_table:
            entries_key = f"{entries_table}:v1:{pending_user_id}"
            entries_cached = _redis_client.get(entries_key)
            if entries_cached:
                entries = json.loads(entries_cached)
                deleted_entry_ids = []
                filtered_entries = []
                
                for entry in entries:
                    if int(entry.get('category_id', 0)) == category_id_int:
                        # This entry belongs to the deleted category
                        entry_id = entry.get('id')
                        if entry_id and int(entry_id) > 0:
                            deleted_entry_ids.append(str(entry_id))
                    else:
                        filtered_entries.append(entry)
                
                # Save filtered entries back to Redis
                _redis_client.setex(
                    entries_key,
                    PERSISTENT_CACHE_TTL,
                    json.dumps(filtered_entries, cls=DecimalEncoder)
                )
                
                # Track pending entry deletions
                if deleted_entry_ids:
                    pending_entries_key = f"pending_deletes:{entries_table}:{pending_user_id}"
                    _redis_client.sadd(pending_entries_key, *deleted_entry_ids)
                    _redis_client.expire(pending_entries_key, PERSISTENT_CACHE_TTL)
                    
                    # Mark entries table as dirty
                    dirty_key = f"dirty_tables:{pending_user_id}"
                    _redis_client.sadd(dirty_key, entries_table)
                    _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        # 2. Delete all buckets for this category
        if buckets_table:
            buckets_key = f"{buckets_table}:v1:{pending_user_id if table_name != 'c_expense_categories' else user_id}"
            buckets_cached = _redis_client.get(buckets_key)
            if buckets_cached:
                buckets = json.loads(buckets_cached)
                deleted_bucket_ids = []
                filtered_buckets = []
                
                for bucket in buckets:
                    if int(bucket.get('category_id', 0)) == category_id_int:
                        # This bucket belongs to the deleted category
                        bucket_id = bucket.get('id')
                        if bucket_id and int(bucket_id) > 0:
                            deleted_bucket_ids.append(str(bucket_id))
                    else:
                        filtered_buckets.append(bucket)
                
                # Save filtered buckets back to Redis
                _redis_client.setex(
                    buckets_key,
                    PERSISTENT_CACHE_TTL,
                    json.dumps(filtered_buckets, cls=DecimalEncoder)
                )
                
                # Track pending bucket deletions
                if deleted_bucket_ids:
                    pending_buckets_key = f"pending_deletes:{buckets_table}:{pending_user_id}"
                    _redis_client.sadd(pending_buckets_key, *deleted_bucket_ids)
                    _redis_client.expire(pending_buckets_key, PERSISTENT_CACHE_TTL)
                    
                    # Mark buckets table as dirty
                    dirty_key = f"dirty_tables:{pending_user_id}"
                    _redis_client.sadd(dirty_key, buckets_table)
                    _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        # 3. Delete the category itself
        redis_key = f"{table_name}:v1:{user_id}"
        cached = _redis_client.get(redis_key)
        if cached:
            rows = json.loads(cached)
            original_count = len(rows)
            rows = [row for row in rows if int(row.get('id')) != category_id_int]
            deleted_count = original_count - len(rows)
            
            # Save back to Redis
            _redis_client.setex(
                redis_key,
                PERSISTENT_CACHE_TTL,
                json.dumps(rows, cls=DecimalEncoder)
            )
            
        
        # Track pending category deletion (only for real MySQL IDs, not temp negative IDs)
        if category_id_int > 0:
            pending_key = f"pending_deletes:{table_name}:{pending_user_id}"
            _redis_client.sadd(pending_key, str(category_id))
            _redis_client.expire(pending_key, PERSISTENT_CACHE_TTL)
        else:
            pass
        
        # Mark category table as dirty
        dirty_key = f"dirty_tables:{pending_user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
    except Exception as e:
        log_error(app.logger, 'REDIS', f"Error deleting category from {table_name} in Redis: {e}")

def _delete_buckets_in_redis(table_name, user_id, category_id):
    """
    Delete all bucket records for a category from Redis cache.
    
    Args:
        table_name: 'recurring_income_buckets', 'recurring_expense_buckets', or 'recurring_c_expense_buckets'
        user_id: User ID (or account_id for c_expense buckets)
        category_id: ID of the category whose buckets should be deleted
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data
        cached = _redis_client.get(redis_key)
        if cached:
            rows = json.loads(cached)
            # Filter out all buckets for this category
            category_id_int = int(category_id)
            original_count = len(rows)
            rows = [row for row in rows if int(row.get('category_id')) != category_id_int]
            deleted_count = original_count - len(rows)
            
            if deleted_count > 0:
                # Save back to Redis
                _redis_client.setex(
                    redis_key,
                    PERSISTENT_CACHE_TTL,
                    json.dumps(rows, cls=DecimalEncoder)
                )
                
                # Mark as dirty
                if table_name == 'recurring_c_expense_buckets':
                    # Get actual user_id for c_expense buckets
                    actual_user_id = current_user.id if current_user.is_authenticated else None
                    if not actual_user_id:
                        account_id = user_id
                        accounts = _get_credit_accounts_from_redis(current_user.id) if current_user.is_authenticated else None
                        if accounts:
                            account = next((a for a in accounts if a.get('id') == account_id), None)
                            if account:
                                actual_user_id = account.get('user_id')
                    dirty_user_id = actual_user_id if actual_user_id else user_id
                else:
                    dirty_user_id = user_id
                
                dirty_key = f"dirty_tables:{dirty_user_id}"
                _redis_client.sadd(dirty_key, table_name)
                _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
                
        
    except Exception as e:
        log_error(app.logger, 'BUCKET', f"Error deleting buckets from {table_name} in Redis: {e}")


def _delete_future_buckets_in_redis(table_name, user_id, category_id, from_date=None):
    """
    Delete future bucket records for a category from Redis cache (from today onwards).
    
    Args:
        table_name: 'recurring_income_buckets', 'recurring_expense_buckets', or 'recurring_c_expense_buckets'
        user_id: User ID
        category_id: ID of the category whose future buckets should be deleted
        from_date: Date to start deleting from (defaults to today)
    """
    if not app.config.get('REDIS_OK'):
        return
    
    if from_date is None:
        from_date = datetime.today().date()
    elif isinstance(from_date, str):
        from_date = datetime.strptime(from_date, '%Y-%m-%d').date()
    
    from_date_str = from_date.isoformat()
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data
        cached = _redis_client.get(redis_key)
        if cached:
            rows = json.loads(cached)
            category_id_int = int(category_id)
            original_count = len(rows)
            
            # Track deleted bucket IDs for pending_deletes
            deleted_bucket_ids = []
            kept_rows = []
            
            for row in rows:
                bucket_category_id = int(row.get('category_id'))
                bucket_date = row.get('bucket_date')
                if isinstance(bucket_date, str):
                    bucket_date_str = bucket_date
                else:
                    bucket_date_str = bucket_date.isoformat() if bucket_date else None
                
                # Keep bucket if it's for a different category OR if the date is before from_date
                if bucket_category_id != category_id_int or (bucket_date_str and bucket_date_str < from_date_str):
                    kept_rows.append(row)
                else:
                    # This bucket should be deleted
                    bucket_id = row.get('id')
                    if bucket_id and int(bucket_id) > 0:
                        deleted_bucket_ids.append(str(bucket_id))
            
            deleted_count = original_count - len(kept_rows)
            
            if deleted_count > 0:
                # Save back to Redis
                _redis_client.setex(
                    redis_key,
                    PERSISTENT_CACHE_TTL,
                    json.dumps(kept_rows, cls=DecimalEncoder)
                )
                
                # Mark bucket IDs as pending deletion
                if deleted_bucket_ids:
                    pending_key = f"pending_deletes:{table_name}:{user_id}"
                    _redis_client.sadd(pending_key, *deleted_bucket_ids)
                    _redis_client.expire(pending_key, PERSISTENT_CACHE_TTL)
                
                # Mark as dirty
                dirty_key = f"dirty_tables:{user_id}"
                _redis_client.sadd(dirty_key, table_name)
                _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
                
        
    except Exception as e:
        log_error(app.logger, 'BUCKET', f"Error deleting future buckets from {table_name} in Redis: {e}")


def _sync_expense_category_to_credit_accounts(user_id, category_name, display_order, group_id=None, is_system=0):
    """
    Sync an expense category to all credit accounts for a user.
    Creates a non-recurring c_expense_category for each credit account.
    
    This ensures expense categories are available across all credit accounts
    for unified category management.
    
    Args:
        user_id: User ID
        category_name: Name of the category
        display_order: Display order from the expense_category
        group_id: Optional expense group ID — mapped to c_expense group via source_group_id
        is_system: Whether this is a system category (0 or 1)
    
    Returns:
        Dictionary mapping account_id -> c_expense_category_id
    """
    created_map = {}  # account_id -> category_id
    
    # Get all credit accounts for this user
    accounts = _get_credit_accounts_from_redis(user_id)
    if accounts is None:
        # Fallback to MySQL
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(dictionary=True)
            cursor.execute("SELECT id FROM credit_accounts WHERE user_id = %s", (user_id,))
            accounts = cursor.fetchall()
            cursor.close()
    
    if not accounts:
        return created_map  # No credit accounts, nothing to sync

    # Pre-fetch c_expense_category_groups to map expense group_id → c_expense group_id per account
    c_groups = _get_category_groups_from_redis('c_expense_category_groups', user_id) or []
    
    for account in accounts:
        account_id = account.get('id')
        
        # Check if category already exists for this account (avoid duplicates)
        existing_categories = _get_categories_from_redis('c_expense_categories', user_id)
        if existing_categories:
            existing_cat = next(
                (cat for cat in existing_categories 
                 if cat.get('account_id') == account_id and cat.get('name') == category_name),
                None
            )
            if existing_cat:
                # Already exists, return the existing ID
                created_map[account_id] = existing_cat.get('id')
                continue

        # Map expense group_id to c_expense group_id for this account
        c_group_id = None
        if group_id is not None:
            c_group = next(
                (cg for cg in c_groups
                 if cg.get('source_group_id') is not None
                 and int(cg['source_group_id']) == int(group_id)
                 and cg.get('account_id') == account_id),
                None
            )
            c_group_id = int(c_group['id']) if c_group else None

        # Determine display_order tier based on group membership
        if existing_categories:
            account_cats = [cat for cat in existing_categories if cat.get('account_id') == account_id]
            if c_group_id is not None:
                # Find the c_group's display_order to use as the tier
                c_grp = next((cg for cg in c_groups if int(cg.get('id', 0)) == c_group_id), None)
                tier = int(float(c_grp.get('display_order', 1))) if c_grp else 1
            elif is_system:
                tier = 0
            else:
                tier = 1
            new_display_order = _next_display_order(account_cats, tier=tier)
        else:
            if is_system:
                new_display_order = 0.0001
            else:
                new_display_order = 1.0001
        
        # Create c_expense category data (always non-recurring)
        c_expense_category = {
            'account_id': account_id,
            'name': category_name,
            'display_order': new_display_order,
            'group_id': c_group_id,
            'is_recurring': 0,  # Always non-recurring when synced
            'no_end_date': 0,
            'hidden': 0,
            'is_bud': 0,
            'is_interest': 0,
            'is_auto_adjustment': 0,
            'is_system': is_system
        }
        
        # Add to Redis
        new_id = _add_category_to_redis('c_expense_categories', user_id, c_expense_category)
        if new_id is not None:
            created_map[account_id] = new_id
        else:
            # Redis failed, try MySQL directly
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("""
                    INSERT INTO c_expense_categories 
                    (account_id, name, display_order, is_recurring, hidden, is_bud, is_interest, is_auto_adjustment, is_system)
                    VALUES (%s, %s, %s, 0, 0, 0, 0, 0, 0)
                """, (account_id, category_name, new_display_order))
                new_id = cursor.lastrowid
                conn.commit()
                cursor.close()
                created_map[account_id] = new_id
    
    return created_map


def _copy_expense_categories_to_new_credit_account(user_id, account_id):
    """
    Copy all existing expense categories to a newly created credit account.
    Also clones expense_category_groups as c_expense_category_groups with source_group_id FK.
    Skips system categories (is_credit_account=1, is_auto_adjustment=1) and
    categories that already exist for this account.
    
    Called when a new credit account is created (manual or the bank provider).
    
    Args:
        user_id: User ID
        account_id: The new credit account's ID (can be temp negative ID)
    
    Returns:
        Number of categories copied
    """
    # Clone expense_category_groups as c_expense_category_groups for this account
    expense_groups = _get_category_groups_from_redis('expense_category_groups', user_id) or []
    exp_group_to_c_group = {}  # expense group_id → c_expense group_id
    for eg in expense_groups:
        eg_id = eg.get('id')
        c_group_id = _add_category_group_to_redis('c_expense_category_groups', user_id, {
            'account_id': account_id,
            'source_group_id': eg_id,
            'name': eg.get('name', ''),
            'display_order': eg.get('display_order', 2)
        })
        if c_group_id is not None:
            exp_group_to_c_group[int(eg_id)] = c_group_id

    # Get all expense categories for this user
    expense_categories = _get_categories_from_redis('expense_categories', user_id)
    if expense_categories is None:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("SELECT * FROM expense_categories WHERE user_id = %s", (user_id,))
            expense_categories = cursor.fetchall()
            cursor.close()
    
    if not expense_categories:
        return 0
    
    # Get existing c_expense categories to check for duplicates
    existing_c_cats = _get_categories_from_redis('c_expense_categories', user_id) or []
    existing_names_for_account = set(
        cat.get('name') for cat in existing_c_cats 
        if cat.get('account_id') == account_id
    )
    
    # Track next display_order per tier
    account_cats = [cat for cat in existing_c_cats if cat.get('account_id') == account_id]
    tier_counters = {}  # tier → next_order
    
    copied = 0
    for exp_cat in expense_categories:
        name = exp_cat.get('name')
        
        # Skip system categories
        if exp_cat.get('is_credit_account') == 1:
            continue
        if exp_cat.get('is_auto_adjustment') == 1:
            continue
        if exp_cat.get('is_system') == 1:
            continue
        
        # Skip if already exists for this account
        if name in existing_names_for_account:
            continue

        # Determine group_id and tier for this c_expense category
        exp_group_id = exp_cat.get('group_id')
        c_group_id = None
        if exp_group_id is not None:
            c_group_id = exp_group_to_c_group.get(int(exp_group_id))

        # Use same tier as the expense category's display_order
        tier = int(float(exp_cat.get('display_order', 1)))
        if tier not in tier_counters:
            tier_counters[tier] = _next_display_order(account_cats, tier=tier)
        next_order = tier_counters[tier]
        tier_counters[tier] = round(next_order + 0.0001, 4)
        
        _add_category_to_redis('c_expense_categories', user_id, {
            'account_id': account_id,
            'name': name,
            'display_order': next_order,
            'group_id': c_group_id,
            'is_recurring': 0,
            'no_end_date': 0,
            'hidden': 0,
            'is_bud': 0,
            'is_interest': 0,
            'is_auto_adjustment': 0,
            'is_system': 0
        })
        copied += 1
    
    if copied > 0:
        log_info(app.logger, 'CATEGORY_SYNC', f"Copied {copied} expense categories to credit account {account_id} for user {user_id}")
    
    return copied


def _sync_rename_to_credit_accounts(user_id, old_name, new_name):
    """
    Rename all c_expense_categories matching old_name to new_name across all credit accounts.
    Called when an expense_category is renamed.
    
    Args:
        user_id: User ID
        old_name: The original category name
        new_name: The new category name
    """
    renamed_count = 0
    
    # Update in Redis
    if app.config.get('REDIS_OK'):
        try:
            redis_key = f"c_expense_categories:v1:{user_id}"
            cached = _redis_client.get(redis_key)
            if cached:
                categories = json.loads(cached)
                for cat in categories:
                    if cat.get('name') == old_name and not cat.get('is_interest') and not cat.get('is_auto_adjustment'):
                        cat['name'] = new_name
                        renamed_count += 1
                if renamed_count > 0:
                    _redis_client.setex(redis_key, 604800, json.dumps(categories, cls=DecimalEncoder))
                    _redis_client.sadd(f"dirty_tables:{user_id}", 'c_expense_categories')
        except Exception as e:
            log_error(app.logger, 'CREDIT', f"Error syncing category rename to c_expense_categories in Redis: {e}")
    
    # Also update MySQL directly for consistency
    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor()
        cursor.execute("""
            UPDATE c_expense_categories SET name = %s
            WHERE name = %s AND is_interest = 0 AND is_auto_adjustment = 0
              AND account_id IN (SELECT id FROM credit_accounts WHERE user_id = %s)
        """, (new_name, old_name, user_id))
        conn.commit()
        cursor.close()
    
    if renamed_count > 0:
        log_info(app.logger, 'CATEGORY_SYNC', f"Renamed '{old_name}' -> '{new_name}' in {renamed_count} c_expense categories for user {user_id}")


def _sync_delete_to_credit_accounts(user_id, category_name):
    """
    Delete all c_expense_categories matching category_name across all credit accounts.
    Called when an expense_category is deleted.
    Moves past entries to Uncategorized, deletes future entries, recurring, and buckets.
    
    Args:
        user_id: User ID
        category_name: The name of the category being deleted
    """
    if not category_name:
        return
    
    deleted_count = 0
    yesterday = date.today() - timedelta(days=1)
    
    # Get all c_expense_categories from Redis
    c_categories = _get_categories_from_redis('c_expense_categories', user_id)
    if not c_categories:
        return
    
    # Find matching categories (skip system categories)
    matching_cats = [cat for cat in c_categories 
                     if cat.get('name') == category_name 
                     and not cat.get('is_interest') 
                     and not cat.get('is_auto_adjustment')]
    
    if not matching_cats:
        return
    
    # Get all c_expense_entries from Redis
    entries = _get_entries_from_redis('c_expense_entries', user_id)
    
    # Group matching categories by account_id to find each account's Uncategorized
    account_ids = set(cat.get('account_id') for cat in matching_cats)
    
    # Build map of account_id -> Uncategorized category_id
    uncat_map = {}
    for cat in c_categories:
        if cat.get('name') == 'Uncategorized' and cat.get('account_id') in account_ids:
            uncat_map[cat.get('account_id')] = cat.get('id')
    
    # Move past entries to Uncategorized for each matching category
    if entries:
        entries_modified = False
        for match_cat in matching_cats:
            cat_id = int(match_cat.get('id'))
            acct_id = match_cat.get('account_id')
            uncat_id = uncat_map.get(acct_id)
            
            if not uncat_id:
                continue
            
            # Find past entries for this category
            past_entries = [e for e in entries 
                          if int(e.get('category_id', 0)) == cat_id 
                          and datetime.strptime(e.get('date'), '%Y-%m-%d').date() <= yesterday]
            
            for old_entry in past_entries:
                entry_date = old_entry.get('date')
                amount = float(old_entry.get('amount', 0))
                
                # Find existing Uncategorized entry for this date
                auto_entry = next((e for e in entries 
                                  if int(e.get('category_id', 0)) == int(uncat_id) 
                                  and e.get('date') == entry_date), None)
                
                if auto_entry:
                    new_amount = float(auto_entry.get('amount', 0)) + amount
                    for i, e in enumerate(entries):
                        if e.get('id') == auto_entry.get('id'):
                            entries[i]['amount'] = new_amount
                            entries[i]['processed'] = 1
                            break
                else:
                    temp_id = -int(time.time() * 1000000) - cat_id
                    new_entry = {
                        'id': temp_id,
                        'category_id': uncat_id,
                        'date': entry_date,
                        'amount': amount,
                        'recurring_id': None,
                        'is_bucket': 0,
                        'original_amount': None,
                        'processed': 1,
                        'bud_item_id': None
                    }
                    entries.append(new_entry)
                
                entries = [e for e in entries if e.get('id') != old_entry.get('id')]
                entries_modified = True
        
        if entries_modified:
            _set_entries_to_redis('c_expense_entries', user_id, entries)
    
    # Delete each matching category (handles entries, recurring, buckets, pending deletes)
    for match_cat in matching_cats:
        cat_id = match_cat.get('id')
        _delete_category_in_redis('c_expense_categories', user_id, cat_id)
        deleted_count += 1
    
    # Also remove recurring_c_expense records for deleted categories
    if app.config.get('REDIS_OK'):
        try:
            recurring_redis_key = f"recurring_c_expense:v1:{user_id}"
            recurring_data = _redis_client.get(recurring_redis_key)
            if recurring_data:
                recurring_list = json.loads(recurring_data)
                cat_ids = set(int(cat.get('id')) for cat in matching_cats)
                filtered = [r for r in recurring_list if int(r.get('category_id', 0)) not in cat_ids]
                if len(filtered) < len(recurring_list):
                    if len(filtered) == 0:
                        _redis_client.delete(recurring_redis_key)
                    else:
                        _redis_client.setex(recurring_redis_key, 604800, json.dumps(filtered, cls=DecimalEncoder))
                    _redis_client.sadd(f"dirty_tables:{user_id}", 'recurring_c_expense')
        except Exception as e:
            log_error(app.logger, 'CATEGORY_SYNC', f"Error removing recurring_c_expense for deleted categories: {e}")
    
    if deleted_count > 0:
        log_info(app.logger, 'CATEGORY_SYNC', f"Deleted '{category_name}' from {deleted_count} c_expense categories for user {user_id}")


def _next_display_order(categories, tier=1):
    """
    Calculate the next display_order value for a new category in the given tier.
    
    Tiers:
        0 = system categories (auto-adjustment, Starting Balance, Uncategorized, etc.)
        1 = ungrouped user categories
        2+ = user-created groups
    
    Args:
        categories: list of category dicts (from Redis or MySQL)
        tier: integer tier (0, 1, or group display_order)
    
    Returns:
        Decimal-compatible float like 1.0005
    """
    tier_cats = [c for c in categories if int(float(c.get('display_order', 0))) == tier]
    if not tier_cats:
        return round(tier + 0.0001, 4)
    max_order = max(float(c.get('display_order', 0)) for c in tier_cats)
    return round(max_order + 0.0001, 4)


def _category_name_exists(table_name, user_id, name, exclude_id=None):
    """
    Check if a category name already exists for a user (case-insensitive).
    
    Args:
        table_name: 'income_categories' or 'expense_categories'
        user_id: User ID
        name: Category name to check
        exclude_id: Category ID to exclude (for renames - don't match itself)
    
    Returns:
        True if a category with this name already exists
    """
    name_lower = name.strip().lower()
    
    # Try Redis first
    categories = _get_categories_from_redis(table_name, user_id)
    if categories is not None:
        for cat in categories:
            if cat.get('name', '').strip().lower() == name_lower:
                if exclude_id and int(cat.get('id')) == int(exclude_id):
                    continue
                return True
        return False
    
    # Fallback to MySQL
    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor()
        if exclude_id:
            cursor.execute(
                f"SELECT COUNT(*) FROM {table_name} WHERE user_id = %s AND LOWER(TRIM(name)) = %s AND id != %s",
                (user_id, name_lower, exclude_id)
            )
        else:
            cursor.execute(
                f"SELECT COUNT(*) FROM {table_name} WHERE user_id = %s AND LOWER(TRIM(name)) = %s",
                (user_id, name_lower)
            )
        count = cursor.fetchone()[0]
        cursor.close()
        return count > 0


def _add_category_to_redis(table_name, user_id, category_data):
    """
    Add a new category to Redis cache.
    
    Args:
        table_name: 'income_categories', 'expense_categories', or 'c_expense_categories'
        user_id: User ID (or account_id for c_expense_categories)
        category_data: Dictionary with category fields
    
    Returns:
        The new category ID (negative temporary ID for new categories)
    """
    if not app.config.get('REDIS_OK'):
        return None
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data or initialize empty list
        cached = _redis_client.get(redis_key)
        rows = json.loads(cached) if cached else []
        
        # Generate a negative temporary ID for the new category
        # (flush worker will replace with MySQL auto-increment ID)
        existing_ids = [int(row.get('id', 0)) for row in rows]
        min_id = min(existing_ids) if existing_ids else 0
        new_id = min_id - 1 if min_id <= 0 else -1
        
        # Add the ID to category data
        category_data['id'] = new_id
        
        # Add to array
        rows.append(category_data)
        
        # Save back to Redis
        _redis_client.setex(
            redis_key,
            PERSISTENT_CACHE_TTL,
            json.dumps(rows, cls=DecimalEncoder)
        )
        
        # Mark as dirty - user_id is now always the actual user_id for all category tables
        dirty_key = f"dirty_tables:{user_id}"
        
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        return new_id
        
    except Exception as e:
        log_error(app.logger, 'REDIS', f"Error adding category to {table_name} in Redis: {e}")
        return None

def _add_categories_batch_to_redis(table_name, user_id, categories_list):
    """
    Add multiple categories to Redis in a SINGLE read-modify-write operation.
    This prevents race conditions with the background flush worker which can 
    overwrite categories added in separate _add_category_to_redis calls.
    
    Args:
        table_name: 'income_categories', 'expense_categories', or 'c_expense_categories'
        user_id: User ID
        categories_list: List of category data dictionaries
    
    Returns:
        List of new category IDs (negative temporary IDs), or empty list on failure.
        IDs are in the same order as categories_list.
    """
    if not app.config.get('REDIS_OK') or not categories_list:
        return []
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Single read
        cached = _redis_client.get(redis_key)
        rows = json.loads(cached) if cached else []
        
        # Generate sequential negative IDs for all new categories
        existing_ids = [int(row.get('id', 0)) for row in rows]
        min_id = min(existing_ids) if existing_ids else 0
        next_id = min_id - 1 if min_id <= 0 else -1
        
        new_ids = []
        for cat_data in categories_list:
            cat_data['id'] = next_id
            new_ids.append(next_id)
            rows.append(cat_data)
            next_id -= 1
        
        # Single write
        _redis_client.setex(
            redis_key,
            PERSISTENT_CACHE_TTL,
            json.dumps(rows, cls=DecimalEncoder)
        )
        
        # Mark as dirty once
        dirty_key = f"dirty_tables:{user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        return new_ids
        
    except Exception as e:
        log_error(app.logger, 'REDIS', f"Error batch-adding categories to {table_name} in Redis: {e}")
        return []


def _update_category_in_redis(table_name, user_id, category_id, updates):
    """
    Update a category in Redis cache.
    
    Args:
        table_name: 'income_categories', 'expense_categories', or 'c_expense_categories'
        user_id: User ID (now always user_id, even for c_expense_categories)
        category_id: ID of the category to update
        updates: Dictionary of fields to update
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data
        cached = _redis_client.get(redis_key)
        if not cached:
            pass
            return
        
        rows = json.loads(cached)
        category_id_int = int(category_id)
        
        # Find and update the category
        updated = False
        for row in rows:
            if int(row.get('id')) == category_id_int:
                row.update(updates)
                updated = True
                break
        
        if not updated:
            pass
            return
        
        # Save back to Redis
        _redis_client.setex(
            redis_key,
            PERSISTENT_CACHE_TTL,
            json.dumps(rows, cls=DecimalEncoder)
        )
        
        # Mark as dirty - user_id is now always the actual user_id for all category tables
        dirty_key = f"dirty_tables:{user_id}"
        
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        
    except Exception as e:
        log_error(app.logger, 'REDIS', f"Error updating category in {table_name} in Redis: {e}")


def _get_categories_from_redis(table_name, user_id):
    """
    Get categories from Redis cache.
    
    Args:
        table_name: 'income_categories', 'expense_categories', or 'c_expense_categories'
        user_id: User ID (now always user_id, even for c_expense_categories)
    
    Returns:
        List of category dictionaries, or None if not in Redis
    """
    if not app.config.get('REDIS_OK'):
        return None
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        cached = _redis_client.get(redis_key)
        return json.loads(cached) if cached else None
    except Exception as e:
        log_error(app.logger, 'REDIS', f"Error getting categories from {table_name} in Redis: {e}")
        return None


