@app.route('/delete-week-entry', methods=['POST'])
@login_required
def delete_week_entry():
    from datetime import datetime
    data = request.get_json()
    category_id = data.get('category_id')
    entry_type = data.get('type')
    start_date = data.get('start_date')
    end_date = data.get('end_date')
    friday_date = data.get('friday_date')  # You may need to pass this from frontend
    bank_partial = data.get('bank_partial', False)
    today_date = data.get('today_date')

    if not all([category_id, entry_type, start_date, end_date]):
        return jsonify({'status': 'error', 'message': 'Missing required parameters'}), 400

    # the bank provider partial delete: calculate past_sum before deleting
    past_sum = 0
    if bank_partial and today_date:
        entries = _get_entries_from_redis(table_name_map.get(entry_type, ''), current_user.id)
        if entries is None:
            entries = []
        for entry in entries:
            entry_cat = int(entry.get('category_id', 0))
            entry_date_str = entry.get('date', '')
            if entry_cat == int(category_id) and start_date <= entry_date_str < today_date:
                past_sum += float(entry.get('amount', 0))
        # Narrow delete range to today onward
        start_date = today_date

    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor(pymysql.cursors.DictCursor)

        # Determine the correct table for deletion
        if entry_type == 'income':
            table_name = 'income_entries'
            category_table = 'income_categories'
        elif entry_type == 'expense':
            table_name = 'expense_entries'
            category_table = 'expense_categories'
        elif entry_type == 'ca':
            table_name = 'c_expense_entries'
            category_table = 'c_expense_categories'
        else:
            cursor.close()
            return jsonify({'status': 'error', 'message': 'Invalid entry type'}), 400

        # Optionally, check that the category_id exists in the correct category table
        cursor.execute(f"SELECT * FROM {category_table} WHERE id = %s", (category_id,))
        cat_row = cursor.fetchone()

        # Make a copy of cat_row data before closing cursor
        cat_data = dict(cat_row) if cat_row else {}
        cursor.close()
    
    # Delete from Redis only - flush worker will persist to MySQL
    _delete_entry_in_redis(table_name, current_user.id, category_id, start_date, end_date)
    
    ca_triggered = False
    # If this is an expense category and is_credit_account=1, delete payment entry and trigger CA balance update
    if entry_type == 'expense' and cat_data.get('is_credit_account', 0) == 1:
        ca_triggered = True
        # Find the credit account using credit_account_id FK
        account_id = cat_data.get('credit_account_id')
        if account_id:
            account_id = int(account_id)
            # Delete payment entries for this account and date range
            _delete_payment_entry_in_redis(current_user.id, account_id, start_date, end_date)

    # If a CA payment was updated, trigger CA balance recalculation
    if ca_triggered or entry_type == 'ca':
        save_ca_daily_balance()
    
    # Get updated bucket information to return to frontend
    # Check if aggregation type was provided (for dashboard_3m vs dashboard)
    aggregation = data.get('aggregation', 'week')  # Default to 'week' for dashboard.html
    # Don't filter by specific_date - return all buckets since the depleted bucket might be in a different period
    updated_buckets = _get_updated_buckets_from_redis(table_name, current_user.id, category_id, aggregation, None)

    response_data = {'status': 'success', 'updated_buckets': updated_buckets}
    if bank_partial:
        response_data['past_sum'] = round(past_sum, 2)
    return jsonify(response_data)

# Helper map for entry_type -> table_name (used by bank_partial logic)
table_name_map = {
    'income': 'income_entries',
    'expense': 'expense_entries',
    'ca': 'c_expense_entries'
}

@app.route('/update-week-entry', methods=['POST'])
@login_required
def update_week_entry():
    data = request.get_json()
    entry_type = data.get('type')
    category_id = int(data.get('category_id')) if data.get('category_id') is not None else None
    amount = data.get('amount')
    friday_date = data.get('friday_date')
    start_date = data.get('start_date')
    end_date = data.get('end_date')
    bank_partial = data.get('bank_partial', False)
    today_date = data.get('today_date')
    entry_date = data.get('entry_date', friday_date)


    if category_id is None or not friday_date or amount is None or not entry_type or not start_date or not end_date:
        missing = []
        if category_id is None: missing.append('category_id')
        if not friday_date: missing.append('friday_date')
        if amount is None: missing.append('amount')
        if not entry_type: missing.append('type')
        if not start_date: missing.append('start_date')
        if not end_date: missing.append('end_date')
        log_error(app.logger, 'UPDATE_WEEK_ENTRY', f"Missing parameters: {', '.join(missing)}")
        return jsonify({"status": "error", "message": f"Missing required parameters: {', '.join(missing)}"}), 400

    # Choose the correct table
    if entry_type == 'income':
        table_name = 'income_entries'
        category_table = 'income_categories'
    elif entry_type == 'expense':
        table_name = 'expense_entries'
        category_table = 'expense_categories'
    elif entry_type == 'ca':
        table_name = 'c_expense_entries'
        category_table = 'c_expense_categories'
    else:
        return jsonify({"status": "error", "message": "Invalid entry type"}), 400

    # Validate category exists (check Redis for temp IDs, MySQL for real IDs)
    cat_data = {}
    if category_id < 0:
        # Temp ID - check Redis
        if entry_type == 'ca':
            # For credit accounts, need to find which account this category belongs to
            # Get all credit accounts and check each one for this category
            credit_accounts = _get_credit_accounts_from_redis(current_user.id)
            
            if credit_accounts is None:
                with get_db_pool().get_connection() as conn:
                    cursor = conn.cursor(pymysql.cursors.DictCursor)
                    cursor.execute("SELECT id FROM credit_accounts WHERE user_id = %s", (current_user.id,))
                    credit_accounts = cursor.fetchall()
                    cursor.close()
            
            # Get all c_expense_categories for user (keyed by user_id)
            category_found = False
            cats = _get_categories_from_redis('c_expense_categories', current_user.id)
            
            if cats:
                # Log all category IDs to see what we're comparing
                cat_ids = [cat.get('id') for cat in cats]
                
                matching_cat = next((cat for cat in cats if cat.get('id') == category_id), None)
                if matching_cat:
                    cat_data = matching_cat
                    category_found = True
            
            if not category_found:
                log_error(app.logger, 'UPDATE_WEEK_ENTRY', f"Invalid temp category_id {category_id} for CA - not found")
                return jsonify({"status": "error", "message": "Invalid category_id - category not found"}), 400
        else:
            # For income/expense, check Redis
            cats = _get_categories_from_redis(category_table, current_user.id)
            
            if cats:
                cat_data = next((cat for cat in cats if cat.get('id') == category_id), None)
                if not cat_data:
                    log_error(app.logger, 'UPDATE_WEEK_ENTRY', f"Category {category_id} not found in {len(cats)} categories")
                    return jsonify({"status": "error", "message": "Invalid category_id for this entry type"}), 400
            else:
                log_error(app.logger, 'UPDATE_WEEK_ENTRY', f"No categories found in Redis for {category_table}")
                return jsonify({"status": "error", "message": "Invalid category_id for this entry type"}), 400
    else:
        # Real ID - check MySQL
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute(f"SELECT * FROM {category_table} WHERE id = %s", (category_id,))
            cat_row = cursor.fetchone()
            if not cat_row:
                cursor.close()
                return jsonify({"status": "error", "message": "Invalid category_id for this entry type"}), 400
            cat_data = dict(cat_row) if cat_row else {}
            cursor.close()

    # For CA entries, get old amount before deletion (for balance calculation)
    old_ca_amount = 0
    if entry_type == 'ca':
        old_entries = _get_entries_from_redis(table_name, current_user.id)
        if old_entries:
            # Sum all entries in the week range for this category
            for entry in old_entries:
                entry_date_val = entry.get('date', '')
                if (int(entry.get('category_id', 0)) == int(category_id) and 
                    start_date <= entry_date_val <= end_date):
                    old_ca_amount += float(entry.get('amount', 0))

    # the bank provider partial edit: calculate past_sum and narrow delete range
    past_sum = 0
    delta_amount = float(amount)
    if bank_partial and today_date:
        entries = _get_entries_from_redis(table_name, current_user.id)
        if entries is None:
            entries = []
        for entry in entries:
            entry_cat = int(entry.get('category_id', 0))
            entry_date_str = entry.get('date', '')
            if entry_cat == int(category_id) and start_date <= entry_date_str < today_date:
                past_sum += float(entry.get('amount', 0))
        if float(amount) < past_sum:
            return jsonify({
                'status': 'error',
                'message': f'Past bank transactions already total ${past_sum:.2f}. New value must be at least ${past_sum:.2f}.',
                'past_sum': round(past_sum, 2)
            }), 400
        delta_amount = float(amount) - past_sum
        # Only delete from today onward
        _delete_entry_in_redis(table_name, current_user.id, category_id, today_date, end_date)
    else:
        # Original behavior - delete all entries in the range
        _delete_entry_in_redis(table_name, current_user.id, category_id, start_date, end_date)
    
    # Check if this is a future-dated entry (should become a bucket)
    from datetime import date as date_type
    if isinstance(entry_date, str):
        entry_date_parsed = date_type.fromisoformat(entry_date)
    else:
        entry_date_parsed = entry_date
    today = date_type.today()
    entry_is_bucket = entry_date_parsed >= today
    
    # Check for bucket entries and deplete them if this is a recurring category OR has manual buckets
    if delta_amount != 0 and not entry_is_bucket:
        pass
        try:
            # Get recurring info for this category to determine cadence from Redis
            if entry_type == 'income':
                recurring_info = _get_recurring_info_from_redis('recurring_income', current_user.id, category_id)
            elif entry_type == 'expense':
                recurring_info = _get_recurring_info_from_redis('recurring_expense', current_user.id, category_id)
            elif entry_type == 'ca':
                # For credit accounts, we need to get the account_id first to get recurring info
                account_id_for_recurring = None
                if category_id < 0:
                    # Temp category - search in Redis (keyed by user_id)
                    cats = _get_categories_from_redis('c_expense_categories', current_user.id)
                    if cats:
                        matching_cat = next((cat for cat in cats if cat.get('id') == category_id), None)
                        if matching_cat:
                            account_id_for_recurring = matching_cat.get('account_id')
                else:
                    # Real category - query MySQL
                    with get_db_pool().get_connection() as conn:
                        cursor = conn.cursor(pymysql.cursors.DictCursor)
                        cursor.execute("SELECT account_id FROM c_expense_categories WHERE id = %s", (category_id,))
                        result = cursor.fetchone()
                        account_id_for_recurring = result['account_id'] if result else None
                        cursor.close()
                
                
                # Note: _get_recurring_info_from_redis uses user_id, not account_id, because 
                # recurring_c_expense:v1:{user_id} stores ALL recurring CA expenses for a user
                recurring_info = _get_recurring_info_from_redis('recurring_c_expense', current_user.id, category_id)
            else:
                recurring_info = None
            
            # Process bucket reduction - works for both recurring and non-recurring categories with buckets
            from bucket_utils import find_next_bucket_for_category
            next_bucket = find_next_bucket_for_category(table_name, category_id, current_user.id)
            if next_bucket:
                log_info(app.logger, 'BUCKET', f"/update-week-entry: Found bucket to reduce: date={next_bucket.get('date')}, amount={next_bucket.get('amount')}")
                process_manual_entry_with_bucket(
                    table_name, category_id, friday_date, 
                    delta_amount, current_user.id, recurring_info
                )
        except Exception as e:
            log_exception(logger, 'BUCKET', f"Error processing bucket depletion: {e}")
            # Continue with normal entry creation even if bucket processing fails
    
    # Update CA balances in Redis immediately if this is a credit account entry
    # Do this BEFORE creating the new entry, so we can calculate the delta
    if entry_type == 'ca':
        pass
        # Get account_id for this category
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            
            # For temp categories, try to find account_id from Redis
            if category_id < 0:
                pass
                # Check all credit accounts to find which one has this category
                credit_accounts = _get_credit_accounts_from_redis(current_user.id)
                if credit_accounts is None:
                    cursor.execute("SELECT id FROM credit_accounts WHERE user_id = %s", (current_user.id,))
                    credit_accounts = cursor.fetchall()
                
                # Get categories keyed by user_id
                account_id_for_balance = None
                cats = _get_categories_from_redis('c_expense_categories', current_user.id)
                if cats:
                    matching_cat = next((cat for cat in cats if cat.get('id') == category_id), None)
                    if matching_cat:
                        account_id_for_balance = matching_cat.get('account_id')
            else:
                pass
                # Real category ID - query MySQL
                cursor.execute("SELECT account_id FROM c_expense_categories WHERE id = %s", (category_id,))
                result = cursor.fetchone()
                account_id_for_balance = result['account_id'] if result else None
            cursor.close()
        
        if account_id_for_balance:
            # Calculate the net change: new_amount - old_amount
            amount_delta = float(amount) - old_ca_amount
            
            
            # Update all three balance tables in Redis
            _update_ca_balances_in_redis('c_a_balances_d', current_user.id, account_id_for_balance, entry_date, amount_delta, is_payment=False)
            _update_ca_balances_in_redis('c_a_balances', current_user.id, account_id_for_balance, entry_date, amount_delta, is_payment=False)
            _update_ca_balances_in_redis('c_a_balances_m', current_user.id, account_id_for_balance, entry_date, amount_delta, is_payment=False)
        else:
            pass
    
    # If delta is 0 (or amount is 0), don't create a new entry (just delete old ones)
    if delta_amount != 0:
        pass
        _update_entry_in_redis(table_name, current_user.id, category_id, entry_date, delta_amount,
                              is_bucket=entry_is_bucket, original_amount=delta_amount if entry_is_bucket else None)
        
        # Create bucket record for future-dated entries
        if entry_is_bucket:
            try:
                from recurring_bucket_manager import create_bucket_record
                # Determine account_id for credit expense entries
                account_id_for_bucket = None
                if entry_type == 'ca':
                    if category_id < 0:
                        # Temp category - search in Redis
                        cats = _get_categories_from_redis('c_expense_categories', current_user.id)
                        if cats:
                            matching_cat = next((cat for cat in cats if cat.get('id') == category_id), None)
                            if matching_cat:
                                account_id_for_bucket = matching_cat.get('account_id')
                    else:
                        # Real category - query MySQL
                        with get_db_pool().get_connection() as conn:
                            cursor = conn.cursor(pymysql.cursors.DictCursor)
                            cursor.execute("SELECT account_id FROM c_expense_categories WHERE id = %s", (category_id,))
                            result = cursor.fetchone()
                            account_id_for_bucket = result['account_id'] if result else None
                            cursor.close()
                
                create_bucket_record(table_name, current_user.id, category_id, entry_date, float(amount), account_id=account_id_for_bucket)
                log_info(app.logger, 'BUCKET', f"/update-week-entry: Created bucket record for future entry: category={category_id}, date={entry_date}, amount={amount}")
            except Exception as e:
                log_exception(logger, 'BUCKET', f"Error creating bucket record: {e}")
    else:
        pass

    # If this is an expense category and is_credit_account=1, create/update payment entry and trigger CA balance update
    ca_triggered = False
    if entry_type == 'expense' and cat_data.get('is_credit_account', 0) == 1:
        ca_triggered = True
        # Find the credit account using credit_account_id FK
        account_id = cat_data.get('credit_account_id')
        if account_id:
            account_id = int(account_id)
            # Update or delete payment entry in Redis based on amount
            if float(amount) == 0:
                pass
                _delete_payment_entry_in_redis(current_user.id, account_id, entry_date, entry_date)
            else:
                pass
                _update_payment_entry_in_redis(current_user.id, account_id, entry_date, float(amount))

    if entry_type == 'ca' or ca_triggered:
        save_ca_daily_balance()

    # Get updated bucket information to return to frontend
    # Check if aggregation type was provided (for dashboard_3m vs dashboard)
    aggregation = data.get('aggregation', 'week')  # Default to 'week' for dashboard.html
    # Don't filter by specific_date - return all buckets since the depleted bucket might be in a different period
    updated_buckets = _get_updated_buckets_from_redis(table_name, current_user.id, category_id, aggregation, None)

    response_data = {"status": "success", "updated_buckets": updated_buckets}
    if bank_partial:
        response_data['past_sum'] = round(past_sum, 2)
    return jsonify(response_data)


