@app.route('/get_month_totals_batch', methods=['GET'])
@login_required
def get_month_totals_batch():
    """
    Batch endpoint to get all monthly totals/remainders for multiple dates in a single request.
    This replaces multiple calls to get_total_income_3m, get_total_expenses_3m, get_remainder_3m, get_last_remainder_3m.
    
    Query params:
        dates: comma-separated list of dates (e.g., "2025-12-01,2025-11-01,2025-10-01")
        
    Returns:
        {
            "status": "success",
            "data": {
                "2025-12-01": {"total_income": 100, "total_expenses": 50, "remainder": 50, "last_month_remainder": 0},
                ...
            }
        }
    """
    dates_param = request.args.get('dates', '')
    if not dates_param:
        return jsonify({'status': 'error', 'message': 'Missing dates parameter'}), 400
    
    dates = [d.strip() for d in dates_param.split(',') if d.strip()]
    
    try:
        result_data = {}
        
        # Get all totals from Redis (single call)
        cached_data = _get_totals_remainders_from_redis('totals_remainders_m', current_user.id)
        
        if cached_data:
            # Build a lookup dict for O(1) access
            cached_lookup = {row.get('date'): row for row in cached_data}
            
            for date in dates:
                if date in cached_lookup:
                    row = cached_lookup[date]
                    result_data[date] = {
                        'total_income': float(row.get('total_income', 0) or 0),
                        'total_expenses': float(row.get('total_expenses', 0) or 0),
                        'remainder': float(row.get('remainder', 0) or 0),
                        'last_month_remainder': float(row.get('last_month_remainder', 0) or 0)
                    }
                else:
                    result_data[date] = {
                        'total_income': 0,
                        'total_expenses': 0,
                        'remainder': 0,
                        'last_month_remainder': 0
                    }
        else:
            # Fallback to MySQL
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                placeholders = ','.join(['%s'] * len(dates))
                cursor.execute(f"""
                    SELECT date, total_income, total_expenses, remainder, last_month_remainder
                    FROM totals_remainders_m
                    WHERE user_id = %s AND date IN ({placeholders})
                """, [current_user.id] + dates)
                
                rows = cursor.fetchall()
                cursor.close()
                
                # Build result from MySQL data
                mysql_lookup = {str(row['date']): row for row in rows}
                for date in dates:
                    if date in mysql_lookup:
                        row = mysql_lookup[date]
                        result_data[date] = {
                            'total_income': float(row.get('total_income', 0) or 0),
                            'total_expenses': float(row.get('total_expenses', 0) or 0),
                            'remainder': float(row.get('remainder', 0) or 0),
                            'last_month_remainder': float(row.get('last_month_remainder', 0) or 0)
                        }
                    else:
                        result_data[date] = {
                            'total_income': 0,
                            'total_expenses': 0,
                            'remainder': 0,
                            'last_month_remainder': 0
                        }
        
        return jsonify({'status': 'success', 'data': result_data})
        
    except Exception as e:
        log_error(app.logger, 'EXPENSE', f"[get_month_totals_batch] Error: {e}")
        return jsonify({'status': 'error', 'message': 'Internal Server Error'}), 500


@app.route('/get_ca_balances_3m_batch', methods=['GET'])
@login_required
def get_ca_balances_3m_batch():
    """
    Batch endpoint to get monthly credit account balances for multiple dates and accounts.
    
    Query params:
        dates: comma-separated list of dates
        
    Returns:
        {
            "status": "success",
            "data": {
                "account_id": {
                    "date": balance,
                    ...
                },
                ...
            }
        }
    """
    dates_param = request.args.get('dates', '')
    
    if not dates_param:
        return jsonify({'status': 'error', 'message': 'Missing dates parameter'}), 400
    
    dates = [d.strip() for d in dates_param.split(',') if d.strip()]
    
    try:
        result_data = {}
        
        # Get all CA balances from Redis (monthly table)
        cached_data = _get_ca_balances_from_redis('c_a_balances_m', current_user.id)
        
        if cached_data:
            # Group by account_id
            for row in cached_data:
                account_id = str(row.get('account_id'))
                date = row.get('date')
                
                if account_id not in result_data:
                    result_data[account_id] = {}
                
                if date in dates:
                    result_data[account_id][date] = float(row.get('balance', 0) or 0)
            
            # Fill in missing dates with 0
            for account_id in result_data:
                for date in dates:
                    if date not in result_data[account_id]:
                        result_data[account_id][date] = 0
        else:
            # Fallback to MySQL
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                placeholders = ','.join(['%s'] * len(dates))
                cursor.execute(f"""
                    SELECT cab.account_id, cab.date, cab.balance
                    FROM c_a_balances_m cab
                    JOIN credit_accounts ca ON cab.account_id = ca.id
                    WHERE ca.user_id = %s AND cab.date IN ({placeholders})
                """, [current_user.id] + dates)
                
                rows = cursor.fetchall()
                cursor.close()
                
                for row in rows:
                    account_id = str(row['account_id'])
                    date = str(row['date'])
                    
                    if account_id not in result_data:
                        result_data[account_id] = {}
                    
                    result_data[account_id][date] = float(row.get('balance', 0) or 0)
        
        return jsonify({'status': 'success', 'data': result_data})
        
    except Exception as e:
        log_error(app.logger, 'CREDIT', f"[get_ca_balances_3m_batch] Error: {e}")
        return jsonify({'status': 'error', 'message': 'Internal Server Error'}), 500


@app.route('/update-processed-status-month-range', methods=['POST'])
@login_required
def update_processed_status_month_range():
    from redis_crud import get_entries, bulk_update_entries
    from datetime import datetime
    
    data = request.get_json()
    category_id = data.get('category_id')
    category_type = data.get('category_type')  # 'income' or 'expense'
    start_date = data.get('start_date')
    end_date = data.get('end_date')
    processed = data.get('processed')

    if not category_id or not category_type or not start_date or not end_date or processed is None:
        return jsonify({'status': 'error', 'message': 'Missing required parameters'}), 400

    try:
        # Determine the table name
        if category_type == 'income':
            table_name = 'income_entries'
        elif category_type == 'expense':
            table_name = 'expense_entries'
        else:
            return jsonify({'status': 'error', 'message': 'Invalid category type'}), 400

        # Parse dates
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d').date()
        end_date_obj = datetime.strptime(end_date, '%Y-%m-%d').date()
        
        # Get all entries for this category (Redis-first)
        all_entries = get_entries(table_name, {'category_id': int(category_id)}, user_id=current_user.id)
        
        
        # Filter entries within date range
        entries_to_update = []
        for entry in all_entries:
            entry_date = entry.get('date')
            # Handle both date objects and string dates
            if isinstance(entry_date, str):
                entry_date = datetime.strptime(entry_date, '%Y-%m-%d').date()
            
            if start_date_obj <= entry_date <= end_date_obj:
                entries_to_update.append(entry)
        
        
        if not entries_to_update:
            return jsonify({'status': 'success', 'message': 'No entries found in date range'})
        
        # Prepare bulk update - convert processed to int
        processed_int = int(processed)
        updates = [{'id': entry['id'], 'processed': processed_int} for entry in entries_to_update]
        
        # Update using Redis-first approach
        success = bulk_update_entries(table_name, updates, user_id=current_user.id)
        
        if success:
            pass
            
            # Calculate if all entries in this date range for this category are now processed
            all_entries_in_range = get_entries(table_name, {'category_id': int(category_id)}, user_id=current_user.id)
            entries_in_date_range = []
            for entry in all_entries_in_range:
                entry_date = entry.get('date')
                if isinstance(entry_date, str):
                    entry_date = datetime.strptime(entry_date, '%Y-%m-%d').date()
                if start_date_obj <= entry_date <= end_date_obj:
                    entries_in_date_range.append(entry)
            
            # Check if all entries are processed - convert to int for comparison
            all_processed = all(int(entry.get('processed', 0)) == 1 for entry in entries_in_date_range) if entries_in_date_range else False
            
            return jsonify({
                'status': 'success',
                'all_processed': all_processed,
                'entries_updated': len(updates)
            })
        else:
            return jsonify({'status': 'error', 'message': 'Failed to update entries'}), 500

    except Exception as e:
        log_exception(app.logger, 'ENTRY', f"Error in update_processed_status_month_range: {str(e)}")
        return jsonify({'status': 'error', 'message': str(e)}), 500

