@app.route('/manage-categories')
@login_required
def manage_categories():
    user_id = current_user.id

    # Try Redis first for income categories
    income_categories = _get_entries_from_redis('income_categories', user_id)
    if income_categories is None:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("SELECT * FROM income_categories WHERE user_id = %s ORDER BY display_order DESC", (user_id,))
            income_categories = cursor.fetchall()
            cursor.close()
    else:
        income_categories = sorted(income_categories, key=lambda x: x.get('display_order', 0) or 0, reverse=True)

    # Try Redis first for expense categories
    expense_categories = _get_entries_from_redis('expense_categories', user_id)
    if expense_categories is None:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("SELECT * FROM expense_categories WHERE user_id = %s ORDER BY display_order DESC", (user_id,))
            expense_categories = cursor.fetchall()
            cursor.close()
    else:
        expense_categories = sorted(expense_categories, key=lambda x: x.get('display_order', 0) or 0, reverse=True)

    # Filter out hidden=0 categories — show ALL categories on this page
    # (hidden ones will get a visual style, but are still shown)

    # Fetch user profile data
    user_data = None
    redis_key = f"users:v1:{user_id}"
    if app.config.get('REDIS_OK'):
        try:
            cached = _redis_client.get(redis_key)
            if cached:
                user_data = json.loads(cached)
        except Exception as e:
            log_error(app.logger, 'REDIS', f"manage_categories user data: {str(e)}")

    if not user_data:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("SELECT profile_picture, first_name, last_name, landing_page, currency_type FROM users WHERE id = %s", (user_id,))
            user_data = cursor.fetchone()
            cursor.close()

    profile_picture = user_data.get('profile_picture') if user_data else None
    first_name = user_data.get('first_name', '') if user_data else ''
    last_name = user_data.get('last_name', '') if user_data else ''
    landing_page = user_data.get('landing_page', 'dashboard_3m') if user_data else 'dashboard_3m'
    currency_type = user_data.get('currency_type', 'USD') if user_data else 'USD'

    # Get unread notification count
    notifications_list = _get_entries_from_redis('notifications', user_id) or []
    unread_notifications_count = sum(1 for n in notifications_list if not n.get('is_read'))

    # Fetch category groups
    income_category_groups = _get_category_groups_from_redis('income_category_groups', user_id)
    if income_category_groups is None:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("SELECT * FROM income_category_groups WHERE user_id = %s ORDER BY display_order DESC", (user_id,))
            income_category_groups = cursor.fetchall()
            cursor.close()
    else:
        income_category_groups = sorted(income_category_groups, key=lambda x: float(x.get('display_order', 0) or 0), reverse=True)

    expense_category_groups = _get_category_groups_from_redis('expense_category_groups', user_id)
    if expense_category_groups is None:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("SELECT * FROM expense_category_groups WHERE user_id = %s ORDER BY display_order DESC", (user_id,))
            expense_category_groups = cursor.fetchall()
            cursor.close()
    else:
        expense_category_groups = sorted(expense_category_groups, key=lambda x: float(x.get('display_order', 0) or 0), reverse=True)

    return render_template(
        'manage_categories.html',
        income_categories=income_categories,
        expense_categories=expense_categories,
        income_category_groups=income_category_groups,
        expense_category_groups=expense_category_groups,
        profile_picture=profile_picture,
        nav_first_name=first_name,
        nav_last_name=last_name,
        landing_page=landing_page,
        currency_type=currency_type,
        unread_notifications_count=unread_notifications_count
    )


@app.route('/settings', methods=['GET'])
@login_required
def settings():
    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor(pymysql.cursors.DictCursor)

        # Fetch profile picture, first name, last name, balance threshold, goofy_week_mode, landing_page, currency_type, mfa_secret, and email_notifications
        # Try Redis first
        user_data = None
        redis_key = f"users:v1:{current_user.id}"
        if app.config.get('REDIS_OK'):
            try:
                cached = _redis_client.get(redis_key)
                if cached:
                    user_data = json.loads(cached)
            except Exception as e:
                log_error(app.logger, 'REDIS', f"settings user data: {str(e)}")
        
        # Fallback to MySQL
        if not user_data:
            cursor.execute("""
                SELECT profile_picture, first_name, last_name, balance_threshold, goofy_week_mode, landing_page, currency_type, mfa_secret, email_notifications
                FROM users 
                WHERE id = %s
            """, (current_user.id,))
            user_data = cursor.fetchone()

        cursor.close()

    # Extract values from the query result
    profile_picture = user_data['profile_picture'] if user_data else None
    first_name = user_data.get('first_name') or '' if user_data else ''
    last_name = user_data.get('last_name') or '' if user_data else ''
    # Convert balance_threshold to float first, then int to handle decimal strings
    balance_threshold = int(float(user_data['balance_threshold'])) if user_data and user_data['balance_threshold'] is not None else 0
    goofy_week_mode = user_data['goofy_week_mode'] if user_data else 0
    landing_page = user_data['landing_page'] if user_data and user_data['landing_page'] else 'dashboard_3m'
    currency_type = user_data['currency_type'] if user_data and 'currency_type' in user_data else 'USD'
    mfa_enabled = bool(user_data['mfa_secret']) if user_data and 'mfa_secret' in user_data else False
    email_notifications = user_data.get('email_notifications', 0) if user_data else 0

    # The SMTP panel moved to the admin console, so this page no longer needs the
    # config. The one thing it still cares about - whether delivery is verified,
    # which gates the notifications toggle - comes from the email_delivery_verified()
    # Jinja global, so there is nothing to pass and no config shape to keep in step.

    # Pass all retrieved data to the template
    return render_template(
        'settings.html',
        current_username=current_user.username,
        profile_picture=profile_picture,
        first_name=first_name,
        last_name=last_name,
        balance_threshold=balance_threshold,
        goofy_week_mode=goofy_week_mode,
        landing_page=landing_page,
        currency_type=currency_type,
        mfa_enabled=mfa_enabled,
        email_notifications=email_notifications
    )

@app.route('/update_email_notifications', methods=['POST'])
@login_required
def update_email_notifications():
    email_notifications = request.form.get('email_notifications', type=int)

    # Turning this ON requires a verified sending address. Enforced here rather
    # than only in the UI, because the UI state is a hint and this is the rule:
    # an opted-in user whose mail silently goes nowhere is the exact failure
    # verification exists to prevent. Turning it OFF is always allowed.
    if email_notifications == 1:
        from instance_settings import is_verified, get_smtp_config
        if not is_verified():
            msg = ('Verify your email address under Email Delivery before turning '
                   'notifications on.') if get_smtp_config()['configured'] else \
                  ('Set up email delivery under Email Delivery before turning '
                   'notifications on.')
            return jsonify({'status': 'error', 'message': msg}), 400

    try:
        # Update in Redis only - flush worker will persist to MySQL
        _update_user_setting_in_redis(current_user.id, 'email_notifications', email_notifications)
        return jsonify({'status': 'success'})
    except Exception as e:
        log_error(app.logger, 'NOTIFICATION', f"Error updating email notifications: {str(e)}")
        return jsonify({'status': 'error', 'message': str(e)}), 500

