@app.route('/update_profile_picture', methods=['POST'])
@login_required
def update_profile_picture():
    if 'profile_picture' not in request.files:
        flash('No file part')
        return redirect(url_for('profile'))

    file = request.files['profile_picture']
    if file.filename == '':
        flash('No selected file')
        return redirect(url_for('profile'))

    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)

        # Get the current user's profile picture from Redis first
        redis_key = f"users:v1:{current_user.id}"
        user_data = None
        if app.config.get('REDIS_OK'):
            try:
                cached = _redis_client.get(redis_key)
                if cached:
                    user_data = json.loads(cached)
            except Exception as e:
                log_error(app.logger, 'REDIS', f"profile picture lookup: {str(e)}")
        
        # Fallback to MySQL if not in Redis
        if not user_data:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                cursor.execute("SELECT profile_picture FROM users WHERE id = %s", (current_user.id,))
                user_data = cursor.fetchone()
                cursor.close()

        # Delete the old profile picture file if it exists
        if user_data and user_data.get('profile_picture'):
            old_filepath = os.path.join(app.config['UPLOAD_FOLDER'], user_data['profile_picture'])
            if os.path.exists(old_filepath):
                os.remove(old_filepath)

        # Open, resize, and save the new profile picture file
        try:
            # Ensure upload folder exists
            os.makedirs(app.config['UPLOAD_FOLDER'], exist_ok=True)
            
            img = Image.open(file)
            
            # Convert RGBA to RGB if necessary (for PNG with transparency)
            if img.mode in ('RGBA', 'LA', 'P'):
                background = Image.new('RGB', img.size, (255, 255, 255))
                if img.mode == 'P':
                    img = img.convert('RGBA')
                background.paste(img, mask=img.split()[-1] if img.mode == 'RGBA' else None)
                img = background
            
            # Resize so the shortest dimension is 150px while maintaining aspect ratio
            width, height = img.size
            if width < height:
                new_width = 150
                new_height = int((150 / width) * height)
            else:
                new_height = 150
                new_width = int((150 / height) * width)
            
            img = img.resize((new_width, new_height), Image.Resampling.LANCZOS)
            
            # Crop to 150x150 from center
            left = (new_width - 150) / 2
            top = (new_height - 150) / 2
            right = left + 150
            bottom = top + 150
            img = img.crop((left, top, right, bottom))
            
            # Save with optimization
            img.save(filepath, optimize=True, quality=85)
        except Exception as e:
            log_error(app.logger, 'PROFILE', f"Error processing image: {str(e)}")
            flash('Error processing image')
            return redirect(url_for('profile'))

        # Update in Redis only - flush worker will persist to MySQL
        _update_user_setting_in_redis(current_user.id, 'profile_picture', filename)

        flash('Profile picture updated successfully.')
        return redirect(url_for('profile'))
    else:
        flash('Invalid file type')
        return redirect(url_for('profile'))

