@app.route('/update_password', methods=['POST'])
@login_required
def update_password():
    new_password = request.form['password']
    mfa_code = request.form.get('mfa_code')
    
    # Check if user has MFA enabled
    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor(pymysql.cursors.DictCursor)
        cursor.execute("SELECT mfa_secret FROM users WHERE id = %s", (current_user.id,))
        user = cursor.fetchone()
        cursor.close()
    
    # If user has MFA enabled, verify the code
    if user and user['mfa_secret']:
        if not mfa_code:
            return jsonify({'status': 'error', 'message': 'MFA code required'}), 400
        
        # Verify MFA code
        totp = pyotp.TOTP(user['mfa_secret'])
        if not totp.verify(mfa_code, valid_window=1):
            return jsonify({'status': 'invalid_mfa', 'message': 'Invalid MFA code. Please try again.'}), 200

    hashed_password = bcrypt.generate_password_hash(new_password).decode('utf-8')

    # Update in Redis only - flush worker will persist to MySQL
    _update_user_setting_in_redis(current_user.id, 'password', hashed_password)

    return jsonify({'status': 'success'}), 200

@app.route('/enable_mfa', methods=['POST'])
@login_required
def enable_mfa():
    try:
        # Verify password if provided (required from settings, optional during setup)
        password = request.form.get('password')
        if password:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                cursor.execute("SELECT password FROM users WHERE id = %s", (current_user.id,))
                user = cursor.fetchone()
                cursor.close()
            
            if not user or not bcrypt.check_password_hash(user['password'], password):
                return jsonify({'status': 'error', 'message': 'Incorrect password'}), 403
        
        # Generate a new secret
        secret = pyotp.random_base32()
        
        # Store in session until verified (not in database)
        session['pending_mfa_secret'] = secret

        # Generate provisioning URI for Google Authenticator
        uri = pyotp.totp.TOTP(secret).provisioning_uri(name=current_user.username, issuer_name="Blankee")

        # Generate QR code as base64
        img = qrcode.make(uri)
        buf = io.BytesIO()
        img.save(buf, format='PNG')
        qr_b64 = base64.b64encode(buf.getvalue()).decode('utf-8')
        qr_url = f"data:image/png;base64,{qr_b64}"

        return jsonify({'status': 'success', 'qr_url': qr_url, 'secret': secret})
    except Exception as e:
        return jsonify({'status': 'error', 'message': str(e)}), 500
    
@app.route('/verify_mfa', methods=['POST'])
@login_required
def verify_mfa():
    code = request.form.get('code')
    
    # Get pending secret from session
    secret = session.get('pending_mfa_secret')
        
    if not secret:
        return jsonify({'status': 'error', 'message': 'No pending MFA setup'}), 400
    
    totp = pyotp.TOTP(secret)
    if totp.verify(code):
        # Verification successful - now save to database
        _update_user_setting_in_redis(current_user.id, 'mfa_secret', secret)
        # Clear from session
        session.pop('pending_mfa_secret', None)
        return jsonify({'status': 'success'})
    else:
        return jsonify({'status': 'error', 'message': 'Invalid code'}), 400

