@app.route('/recurring-expense')
@login_required
def recurring_expense():
    # Try Redis first
    recurring_expense_records = _get_recurring_from_redis('recurring_expense', current_user.id)
    
    # Get expense categories to filter out credit account categories
    expense_categories = _get_categories_from_redis('expense_categories', current_user.id)
    if expense_categories is None:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("SELECT id, name, is_credit_account FROM expense_categories WHERE user_id = %s", (current_user.id,))
            expense_categories = cursor.fetchall()
            cursor.close()
    
    # Build set of credit account category IDs to exclude
    credit_account_category_ids = {
        int(cat['id']) for cat in expense_categories 
        if cat.get('is_credit_account') == 1 or cat.get('is_credit_account') == '1'
    }
    
    if recurring_expense_records is None:
        # Fallback to MySQL
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            
            # Fetch recurring expense records (including credit account payment categories)
            cursor.execute("""
                SELECT ri.id, ri.user_id, ri.category_id, ic.name as category_name, ri.amount, 
                       ri.cadence_interval, ri.cadence_unit, ri.weekdays, ri.monthly_days, 
                       ri.start_date, ri.end_date, ri.yearly_day, ri.yearly_month,
                       ic.no_end_date, ri.wage_bill
                FROM recurring_expense ri
                JOIN expense_categories ic ON ri.category_id = ic.id
                WHERE ri.user_id = %s
            """, (current_user.id,))

            recurring_expense_records = cursor.fetchall()
            cursor.close()
            
            # Cache to Redis (note: Redis stores ALL recurring expenses, we filter on display)
            # Don't cache the filtered results - get fresh from Redis if needed
    else:
        # Ensure all records have category_name
        needs_enrichment = any('category_name' not in rec or not rec.get('category_name') for rec in recurring_expense_records)
        
        if needs_enrichment:
            # Create a lookup dict from categories we already have
            category_lookup = {int(cat['id']): cat['name'] for cat in expense_categories}
            
            # Enrich the recurring records
            for rec in recurring_expense_records:
                if 'category_name' not in rec or not rec.get('category_name'):
                    rec['category_name'] = category_lookup.get(int(rec['category_id']), 'Unknown')
    
    # Fetch user profile data
    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor(pymysql.cursors.DictCursor)
        cursor.execute("SELECT profile_picture, first_name, last_name, landing_page, currency_type FROM users WHERE id = %s", (current_user.id,))
        user_data = cursor.fetchone()
        cursor.close()

    profile_picture = user_data['profile_picture'] if user_data else None
    first_name = user_data['first_name'] if user_data else ''
    last_name = user_data['last_name'] if user_data else ''
    landing_page = user_data['landing_page'] if user_data and user_data['landing_page'] else 'dashboard_3m'
    currency_type = user_data['currency_type'] if user_data and 'currency_type' in user_data else 'USD'

    # Calculate December 31st, 3 years from now
    current_date = date.today()
    no_end_date = date(current_date.year + 3, 12, 31)

    # Get bucket records for calculating spent amounts
    bucket_records = _get_entries_from_redis('recurring_expense_buckets', current_user.id) or []
    
    # Create lookup for bucket records by category_id (use int for consistent comparison)
    # Track both current bucket and previous (latest past) bucket per category
    today_str = date.today().isoformat()
    bucket_by_category = {}
    prev_bucket_by_category = {}
    _buckets_by_cat = {}
    for bucket in bucket_records:
        cat_id = int(bucket.get('category_id')) if bucket.get('category_id') is not None else None
        bucket_date = bucket.get('bucket_date')
        if cat_id is None or not bucket_date:
            continue
        _buckets_by_cat.setdefault(cat_id, []).append(bucket)
    for cat_id, buckets in _buckets_by_cat.items():
        buckets.sort(key=lambda b: b.get('bucket_date') if isinstance(b.get('bucket_date'), str) else b.get('bucket_date').isoformat())
        future_buckets = [b for b in buckets if (b.get('bucket_date') if isinstance(b.get('bucket_date'), str) else b.get('bucket_date').isoformat()) >= today_str]
        past_buckets = [b for b in buckets if (b.get('bucket_date') if isinstance(b.get('bucket_date'), str) else b.get('bucket_date').isoformat()) < today_str]
        if future_buckets:
            bucket_by_category[cat_id] = future_buckets[0]
        elif past_buckets:
            bucket_by_category[cat_id] = past_buckets[-1]
        current = bucket_by_category.get(cat_id)
        if current and past_buckets:
            current_date_str = current.get('bucket_date') if isinstance(current.get('bucket_date'), str) else current.get('bucket_date').isoformat()
            for b in reversed(past_buckets):
                b_date_str = b.get('bucket_date') if isinstance(b.get('bucket_date'), str) else b.get('bucket_date').isoformat()
                if b_date_str != current_date_str:
                    prev_bucket_by_category[cat_id] = b
                    break

    # Format cadence for display and check for 'No end date'
    for record in recurring_expense_records:
        # Ensure dates are strings (MySQL returns datetime.date objects)
        if isinstance(record.get('start_date'), date):
            record['start_date'] = record['start_date'].strftime('%Y-%m-%d')
        if isinstance(record.get('end_date'), date):
            record['end_date'] = record['end_date'].strftime('%Y-%m-%d')
        
        record['cadence_description'] = get_cadence_description(
            record['cadence_interval'], 
            record['cadence_unit'], 
            record['weekdays'], 
            record['monthly_days'], 
            record['yearly_day'], 
            record['yearly_month']
        )
        # Check if the end_date equals 'no_end_date'
        if record['end_date'] == no_end_date.strftime('%Y-%m-%d'):
            record['display_end_date'] = 'No end date'
        else:
            record['display_end_date'] = record['end_date']
        
        # Add bucket information
        cat_id = int(record.get('category_id')) if record.get('category_id') is not None else None
        bucket_record = bucket_by_category.get(cat_id)
        
        if bucket_record:
            original_amount = float(bucket_record.get('original_amount', 0))
            current_amount = float(bucket_record.get('amount', 0))
            spent_amount = original_amount - current_amount
            record['bucket_original'] = original_amount
            record['bucket_remaining'] = current_amount
            record['bucket_spent'] = spent_amount
            record['bucket_date'] = bucket_record.get('bucket_date')
        else:
            record['bucket_original'] = None
            record['bucket_remaining'] = None
            record['bucket_spent'] = None
            record['bucket_date'] = None
        prev_record = prev_bucket_by_category.get(cat_id)
        if prev_record:
            prev_orig = float(prev_record.get('original_amount', 0))
            prev_cur = float(prev_record.get('amount', 0))
            record['prev_bucket_original'] = prev_orig
            record['prev_bucket_spent'] = prev_orig - prev_cur
            record['prev_bucket_date'] = prev_record.get('bucket_date')
        else:
            record['prev_bucket_original'] = None
            record['prev_bucket_spent'] = None
            record['prev_bucket_date'] = None

    # Pass landing_page to the template
    # Get all expense categories for the searchable dropdown
    all_expense_categories = expense_categories

    return render_template(
        'recurring_e.html', 
        recurring_expense_records=recurring_expense_records,
        expense_categories=all_expense_categories,
        profile_picture=profile_picture,
        first_name=first_name,
        last_name=last_name,
        current_date=current_date,
        landing_page=landing_page,
        currency_type=currency_type
    )

@app.route('/add-recurring-expense', methods=['POST'])
@login_required
def add_recurring_expense():
    # Extract JSON data from the request
    data = request.get_json()

    if not data:
        return jsonify({'status': 'error', 'message': 'No data received'}), 400

    # Extract data from the request
    category_name = data.get('category_name')
    category_id = data.get('category_id')  # For selecting an existing category
    amount = data.get('amount')
    cadence_interval = data.get('cadence_interval')
    cadence_unit = data.get('cadence_unit')
    start_date = data.get('start_date')
    end_date = data.get('end_date')
    weekdays = data.get('weekdays')
    monthly_days = data.get('monthly_days')
    yearly_day = data.get('yearly_day')
    yearly_month = data.get('yearly_month')
    no_end_date = data.get('no_end_date', 0)
    wage_bill = data.get('wage_bill', 0)

    # Validate the data - need either category_name or category_id
    if not category_id and not category_name:
        return jsonify({'status': 'error', 'message': 'Missing category name or ID'}), 400
    if not all([amount, cadence_interval, cadence_unit, start_date, end_date]):
        return jsonify({'status': 'error', 'message': 'Missing required fields'}), 400

    try:
        if category_id:
            # Using an existing category - update it to be recurring
            categories = _get_categories_from_redis('expense_categories', current_user.id)
            if categories:
                cat = next((c for c in categories if str(c['id']) == str(category_id)), None)
                if cat:
                    cat['is_recurring'] = 1
                    cat['no_end_date'] = no_end_date
                    _update_category_in_redis('expense_categories', current_user.id, category_id, cat)
                    category_name = cat['name']
                else:
                    return jsonify({'status': 'error', 'message': 'Category not found'}), 404
            else:
                return jsonify({'status': 'error', 'message': 'Could not load categories'}), 500
        else:
            # Check for duplicate name before creating
            if _category_name_exists('expense_categories', current_user.id, category_name):
                return jsonify({'status': 'error', 'message': f'An expense category named \"{category_name.strip()}\" already exists.'}), 400

            # Step 1: Get next display_order in ungrouped tier (1.YYYY)
            categories = _get_categories_from_redis('expense_categories', current_user.id)
            if categories is not None:
                new_display_order = _next_display_order(categories, tier=1)
            else:
                with get_db_pool().get_connection() as conn:
                    cursor = conn.cursor()
                    cursor.execute("""
                        SELECT COALESCE(MAX(display_order), 1.0) FROM expense_categories WHERE user_id = %s AND FLOOR(display_order) = 1
                    """, (current_user.id,))
                    new_display_order = round(float(cursor.fetchone()[0]) + 0.0001, 4)
                    cursor.close()

            # Step 2: Create category in Redis first (flush worker will sync to MySQL)
            new_category = {
                'user_id': current_user.id,
                'name': category_name,
                'display_order': new_display_order,
                'group_id': None,
                'is_recurring': 1,
                'is_auto_adjustment': 0,
                'no_end_date': no_end_date,
                'hidden': 0,
                'is_bud': 0,
                'is_credit_account': 0,
                'is_system': 0
            }
            
            category_id = _add_category_to_redis('expense_categories', current_user.id, new_category)
            
            if category_id is None:
                return jsonify({'status': 'error', 'message': 'Failed to create category'}), 500

            # Sync to all credit accounts (creates NON-RECURRING c_expense categories)
            _sync_expense_category_to_credit_accounts(current_user.id, category_name, new_display_order)

        # Step 3: Create recurring expense record in Redis
        recurring_data = {
            'id': None,  # Will be generated by Redis helper
            'user_id': current_user.id,
            'category_id': category_id,
            'category_name': category_name,  # Include the category name
            'amount': float(amount),
            'cadence_interval': cadence_interval,
            'cadence_unit': cadence_unit,
            'weekdays': ','.join(weekdays) if weekdays else None,
            'monthly_days': ','.join(map(str, monthly_days)) if monthly_days else None,
            'yearly_day': yearly_day if yearly_day else None,
            'yearly_month': yearly_month if yearly_month else None,
            'start_date': start_date,
            'end_date': end_date,
            'no_end_date': no_end_date,
            'wage_bill': wage_bill
        }
        
        _update_recurring_in_redis('recurring_expense', current_user.id, recurring_data)
        
        # Use a temporary ID for generating entries (will be replaced on flush)
        recurring_id = recurring_data['id']

        # Generate expense entries based on the cadence
        # Now writes to Redis, so works with both temp (negative) and real (positive) IDs
        if recurring_id:
            generate_expense_entries(
                recurring_id, category_id, amount, cadence_interval, cadence_unit,
                start_date, end_date, weekdays, monthly_days, yearly_day, yearly_month, current_user.id
            )
        
        # Recalculate credit account balances if this is a payment category
        if categories:
            cat = next((c for c in categories if str(c.get('id')) == str(category_id)), None)
            if cat and cat.get('is_credit_account') == 1:
                save_ca_daily_balance()
        
        
        # Self-healing: remove any suggestion for this category
        try:
            delete_recurring_suggestion('recurring_expense', category_id, user_id=current_user.id)
        except Exception:
            pass
        
        return jsonify({'status': 'success', 'recurring_id': recurring_id, 'message': 'Recurring expense added successfully!'})

    except Exception as e:
        return jsonify({'status': 'error', 'message': f'An error occurred while adding the recurring expense: {str(e)}'}), 500


def generate_expense_entries(recurring_id, category_id, amount, cadence_interval, cadence_unit, start_date_str, end_date_str, weekdays=None, monthly_days=None, yearly_day=None, yearly_month=None, user_id=None):
    # Get user_id from the category if not provided
    if user_id is None:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("SELECT user_id FROM expense_categories WHERE id = %s", (category_id,))
            result = cursor.fetchone()
            cursor.close()
            if not result:
                return
            user_id = result['user_id']

    # Check if this is a payment category (is_credit_account=1) to also create c_payment_entries
    payment_account_id = None
    categories = _get_categories_from_redis('expense_categories', user_id)
    if categories:
        cat = next((c for c in categories if int(c.get('id', 0)) == int(category_id)), None)
        if cat and cat.get('is_credit_account') == 1 and cat.get('credit_account_id'):
            payment_account_id = int(cat['credit_account_id'])

    start_date = datetime.strptime(start_date_str, '%Y-%m-%d').date()
    current_date = start_date
    end_date = datetime.strptime(end_date_str, '%Y-%m-%d').date()

    log_info(app.logger, 'GEN_EXPENSE_ENTRIES', f"START: recurring_id={recurring_id}, cat_id={category_id}, amount={amount}, cadence={cadence_interval}/{cadence_unit}, start={start_date}, end={end_date}, monthly_days={monthly_days}, payment_account_id={payment_account_id}")
    _gen_entries_count = 0

    while current_date <= end_date:
        delta = None

        if cadence_unit == 'days':
            # Create bucket entry and record
            _create_bucket_entry_and_record('expense_entries', user_id, category_id, current_date, amount, recurring_id)
            # Also create payment entry if this is a payment category
            if payment_account_id:
                _update_payment_entry_in_redis(user_id, payment_account_id, current_date, float(amount))
            delta = timedelta(days=int(cadence_interval))

        elif cadence_unit == 'weeks':
            for weekday in weekdays:
                weekday_num = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'].index(weekday)
                weekday_date = current_date + timedelta(days=(weekday_num - current_date.weekday()) % 7)
                if start_date <= weekday_date <= end_date:
                    # Create bucket entry and record
                    _create_bucket_entry_and_record('expense_entries', user_id, category_id, weekday_date, amount, recurring_id)
                    # Also create payment entry if this is a payment category
                    if payment_account_id:
                        _update_payment_entry_in_redis(user_id, payment_account_id, weekday_date, float(amount))
            delta = timedelta(weeks=int(cadence_interval))

        elif cadence_unit == 'months':
                if monthly_days:
                    # Convert all days to int, except 'Last Day'
                    monthly_days_cleaned = []
                    for day in monthly_days:
                        if str(day).lower() == 'last day':
                            monthly_days_cleaned.append('Last Day')
                        else:
                            try:
                                monthly_days_cleaned.append(int(day))
                            except Exception:
                                continue

                    # Loop through each month from start_date to end_date
                    year = current_date.year
                    month = current_date.month
                    log_info(app.logger, 'GEN_EXPENSE_ENTRIES', f"Months loop start: year={year}, month={month}, monthly_days_cleaned={monthly_days_cleaned}")
                    while True:
                        for day in monthly_days_cleaned:
                            try:
                                if str(day).lower() == 'last day':
                                    day_num = calendar.monthrange(year, month)[1]
                                else:
                                    day_num = int(day)
                                    last_day_of_month = calendar.monthrange(year, month)[1]
                                    if day_num > last_day_of_month:
                                        continue  # Skip invalid days
                                entry_date = date(year=year, month=month, day=day_num)
                            except Exception as _ex:
                                log_error(app.logger, 'GEN_EXPENSE_ENTRIES', f"Exception in date creation: {_ex}")
                                continue
                            if entry_date < start_date:
                                continue
                            if entry_date > end_date:
                                continue
                            # Create bucket entry and record
                            _create_bucket_entry_and_record('expense_entries', user_id, category_id, entry_date, amount, recurring_id)
                            _gen_entries_count += 1
                            # Also create payment entry if this is a payment category
                            if payment_account_id:
                                _update_payment_entry_in_redis(user_id, payment_account_id, entry_date, float(amount))
                        # Move to next month by cadence_interval
                        month += int(cadence_interval)
                        while month > 12:
                            month -= 12
                            year += 1
                        # Stop if we've passed the end date's year and month
                        if (year > end_date.year) or (year == end_date.year and month > end_date.month):
                            break
                    log_info(app.logger, 'GEN_EXPENSE_ENTRIES', f"Months loop done: entries_created={_gen_entries_count}")
                else:
                    # Default to the first day of each month
                    year = current_date.year
                    month = current_date.month
                    while True:
                        entry_date = date(year=year, month=month, day=1)
                        if entry_date < start_date:
                            pass
                        elif entry_date > end_date:
                            break
                        else:
                            # Create bucket entry and record
                            _create_bucket_entry_and_record('expense_entries', user_id, category_id, entry_date, amount, recurring_id)
                            # Also create payment entry if this is a payment category
                            if payment_account_id:
                                _update_payment_entry_in_redis(user_id, payment_account_id, entry_date, float(amount))
                        # Move to next month by cadence_interval
                        month += int(cadence_interval)
                        while month > 12:
                            month -= 12
                            year += 1
                        if (year > end_date.year) or (year == end_date.year and month > end_date.month):
                            break
                break  # Exit the outer while loop after handling months

        elif cadence_unit == 'years':
            if yearly_day and yearly_month:
                interval = int(cadence_interval)
                year = start_date.year
                while True:
                    try:
                        yearly_entry_date = date(year=year, month=int(yearly_month), day=int(yearly_day))
                    except ValueError:
                        year += interval
                        continue
                    if yearly_entry_date < start_date:
                        year += interval
                        continue
                    if yearly_entry_date > end_date:
                        break
                    # Create bucket entry and record
                    _create_bucket_entry_and_record('expense_entries', user_id, category_id, yearly_entry_date, amount, recurring_id)
                    # Also create payment entry if this is a payment category
                    if payment_account_id:
                        _update_payment_entry_in_redis(user_id, payment_account_id, yearly_entry_date, float(amount))
                    year += interval
            else:
                interval = int(cadence_interval)
                year = start_date.year
                while True:
                    yearly_entry_date = date(year=year, month=1, day=1)
                    if yearly_entry_date < start_date:
                        year += interval
                        continue
                    if yearly_entry_date > end_date:
                        break
                    # Create bucket entry and record
                    _create_bucket_entry_and_record('expense_entries', user_id, category_id, yearly_entry_date, amount, recurring_id)
                    # Also create payment entry if this is a payment category
                    if payment_account_id:
                        _update_payment_entry_in_redis(user_id, payment_account_id, yearly_entry_date, float(amount))
                    year += interval

        # Increment current_date
        if delta:
            current_date += delta
        else:
            break

@app.route('/delete-recurring-expense', methods=['POST'])
@login_required
def delete_recurring_expense():
    try:
        data = request.get_json()
        recurring_id = data.get('recurring_id')
        if not recurring_id:
            return jsonify({'status': 'error', 'message': 'Recurring ID not provided.'}), 400

        # Find the recurring record in Redis
        category_id = None
        cached_recurring = _get_recurring_from_redis('recurring_expense', current_user.id)
        if cached_recurring:
            for rec in cached_recurring:
                if int(rec.get('id')) == int(recurring_id):
                    category_id = rec.get('category_id')
                    break
        
        # If not found in Redis, check MySQL to get category_id
        if category_id is None:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("""
                    SELECT category_id FROM recurring_expense WHERE id = %s AND user_id = %s
                """, (recurring_id, current_user.id))
                category = cursor.fetchone()
                cursor.close()
                if not category:
                    return jsonify({'status': 'error', 'message': 'Recurring expense not found.'}), 404
                category_id = category[0]
        
        if not category_id:
            return jsonify({'status': 'error', 'message': 'Category ID not found for recurring expense.'}), 404
        
        # Convert to non-recurring instead of deleting the category
        # Keep past entries, remove future entries, remove recurring/bucket records
        today = date.today()
        category_id_int = int(category_id)
        
        # Check if this is a payment category (is_credit_account=1) to also remove c_payment_entries
        payment_account_id = None
        categories = _get_categories_from_redis('expense_categories', current_user.id)
        if categories:
            cat = next((c for c in categories if int(c.get('id', 0)) == category_id_int), None)
            if cat and cat.get('is_credit_account') == 1 and cat.get('credit_account_id'):
                payment_account_id = int(cat['credit_account_id'])
        
        # 1. Remove future entries (today and onward), keep past entries
        entries = _get_entries_from_redis('expense_entries', current_user.id)
        if entries:
            filtered_entries = []
            deleted_entry_ids = []
            for e in entries:
                if int(e.get('category_id', 0)) == category_id_int:
                    entry_date = datetime.strptime(e.get('date'), '%Y-%m-%d').date() if isinstance(e.get('date'), str) else e.get('date')
                    if entry_date >= today:
                        # Future entry - mark for deletion
                        entry_id = e.get('id')
                        if entry_id and int(entry_id) > 0:
                            deleted_entry_ids.append(str(entry_id))
                    else:
                        # Past entry - keep
                        filtered_entries.append(e)
                else:
                    filtered_entries.append(e)
            
            if len(filtered_entries) < len(entries):
                _set_entries_to_redis('expense_entries', current_user.id, filtered_entries)
                
                # Track pending entry deletions
                if deleted_entry_ids and app.config.get('REDIS_OK'):
                    pending_key = f"pending_deletes:expense_entries:{current_user.id}"
                    _redis_client.sadd(pending_key, *deleted_entry_ids)
                    _redis_client.expire(pending_key, 604800)
                    _redis_client.sadd(f"dirty_tables:{current_user.id}", 'expense_entries')
        
        # 1b. If this is a payment category, also remove future c_payment_entries
        if payment_account_id:
            _delete_payment_entry_in_redis(current_user.id, payment_account_id, today, date(9999, 12, 31))
        
        # 2. Delete all buckets for this category from Redis
        _delete_buckets_in_redis('recurring_expense_buckets', current_user.id, category_id)
        
        # 3. Delete the recurring record from Redis (marks for deletion)
        _delete_recurring_in_redis('recurring_expense', current_user.id, recurring_id)
        
        # 3b. Clean up any associated mismatch record
        try:
            from redis_crud import delete_recurring_mismatch
            delete_recurring_mismatch('recurring_expense', recurring_id, user_id=current_user.id)
        except Exception:
            pass
        
        # 4. Set category to non-recurring (keep the category itself)
        _update_category_in_redis('expense_categories', current_user.id, category_id, {
            'is_recurring': 0,
            'no_end_date': 0
        })
        
        
        # Recalculate credit account balances if payment entries were modified
        if payment_account_id:
            save_ca_daily_balance()
        
        return jsonify({'status': 'success', 'message': 'Recurring expense converted to regular category.'})

    except Exception as e:
        log_error(app.logger, 'EXPENSE', f"Error deleting recurring expense: {e}")
        return jsonify({'status': 'error', 'message': 'An error occurred while deleting the recurring expense.'}), 500


@app.route('/convert-to-recurring-expense', methods=['POST'])
@login_required
def convert_to_recurring_expense():
    """Convert an existing non-recurring expense category to recurring."""
    data = request.get_json()
    if not data:
        return jsonify({'status': 'error', 'message': 'No data received'}), 400

    category_id = data.get('category_id')
    amount = data.get('amount')
    cadence_interval = data.get('cadence_interval')
    cadence_unit = data.get('cadence_unit')
    start_date = data.get('start_date')
    end_date = data.get('end_date')
    weekdays = data.get('weekdays')
    monthly_days = data.get('monthly_days')
    yearly_day = data.get('yearly_day')
    yearly_month = data.get('yearly_month')
    no_end_date = data.get('no_end_date', 0)
    wage_bill = data.get('wage_bill', 0)

    if not all([category_id, amount, cadence_interval, cadence_unit, start_date, end_date]):
        return jsonify({'status': 'error', 'message': 'Missing required fields'}), 400

    try:
        # Verify the category exists and belongs to this user
        categories = _get_categories_from_redis('expense_categories', current_user.id)
        category_name = None
        if categories is not None:
            for cat in categories:
                if int(cat.get('id')) == int(category_id) and int(cat.get('user_id', 0)) == current_user.id:
                    category_name = cat.get('name')
                    break

        if category_name is None:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("""
                    SELECT name FROM expense_categories WHERE id = %s AND user_id = %s
                """, (category_id, current_user.id))
                row = cursor.fetchone()
                cursor.close()
                if row:
                    category_name = row[0]
                else:
                    return jsonify({'status': 'error', 'message': 'Invalid category'}), 400

        # Mark the category as recurring in Redis
        _update_category_in_redis('expense_categories', current_user.id, category_id, {
            'is_recurring': 1,
            'no_end_date': no_end_date
        })

        # Create recurring expense record in Redis
        recurring_data = {
            'id': None,
            'user_id': current_user.id,
            'category_id': int(category_id),
            'category_name': category_name,
            'amount': float(amount),
            'cadence_interval': cadence_interval,
            'cadence_unit': cadence_unit,
            'weekdays': ','.join(weekdays) if weekdays else None,
            'monthly_days': ','.join(map(str, monthly_days)) if monthly_days else None,
            'yearly_day': yearly_day if yearly_day else None,
            'yearly_month': yearly_month if yearly_month else None,
            'start_date': start_date,
            'end_date': end_date,
            'no_end_date': no_end_date,
            'wage_bill': wage_bill
        }

        _update_recurring_in_redis('recurring_expense', current_user.id, recurring_data)

        recurring_id = recurring_data['id']

        if recurring_id:
            generate_expense_entries(
                recurring_id, int(category_id), amount, cadence_interval, cadence_unit,
                start_date, end_date, weekdays, monthly_days, yearly_day, yearly_month, current_user.id
            )

        # Recalculate credit account balances if this is a payment category
        if categories:
            cat = next((c for c in categories if int(c.get('id', 0)) == int(category_id)), None)
            if cat and cat.get('is_credit_account') == 1:
                save_ca_daily_balance()


        return jsonify({'status': 'success', 'recurring_id': recurring_id, 'message': 'Category converted to recurring successfully!'})

    except Exception as e:
        log_error(app.logger, 'EXPENSE', f"Error converting expense to recurring: {e}")
        return jsonify({'status': 'error', 'message': f'An error occurred: {str(e)}'}), 500


@app.route('/update-recurring-expense', methods=['POST'])
@login_required
def update_recurring_expense():
    data = request.get_json()
    return update_recurring_expense_inner(data, current_user.id)

def update_recurring_expense_inner(data, user_id):
    try:
        # Get the request data sent via AJAX
        recurring_id = data.get('recurring_id')
        category_name = data.get('category_name')
        amount = data.get('amount')
        cadence_interval = data.get('cadence_interval')
        cadence_unit = data.get('cadence_unit')
        start_date = data.get('start_date')
        end_date = data.get('end_date')
        weekdays = data.get('weekdays')  # Extract the weekdays array
        monthly_days = data.get('monthly_days')  # Extract the array of monthly days, if any
        yearly_day = data.get('yearly_day')  # Extract the yearly day, if any
        yearly_month = data.get('yearly_month')  # Extract the yearly month, if any
        no_end_date = data.get('no_end_date', 0)
        wage_bill = data.get('wage_bill', 0)

        # Validate the data
        if not all([recurring_id, category_name, amount, cadence_interval, cadence_unit, start_date, end_date]):
            return jsonify({'status': 'error', 'message': 'Missing required fields'}), 400

        # Ensure that the start date is today or later
        today = datetime.today().date()
        if datetime.strptime(start_date, '%Y-%m-%d').date() < today:
            return jsonify({'status': 'error', 'message': 'Start date cannot be earlier than today'}), 400

        # Ensure that the end date is not earlier than the start date
        if datetime.strptime(end_date, '%Y-%m-%d') < datetime.strptime(start_date, '%Y-%m-%d'):
            return jsonify({'status': 'error', 'message': 'End date cannot be earlier than start date'}), 400

        # First, try to find the recurring record in Redis (handles temp negative IDs)
        cached_recurring = _get_recurring_from_redis('recurring_expense', user_id)
        category_id = None
        
        if cached_recurring:
            for rec in cached_recurring:
                if int(rec.get('id')) == int(recurring_id):
                    category_id = rec.get('category_id')
                    break
        
        # If not in Redis, fall back to MySQL
        if not category_id:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("""
                    SELECT category_id FROM recurring_expense WHERE id = %s AND user_id = %s
                """, (recurring_id, user_id))
                result = cursor.fetchone()
                cursor.close()
                if not result:
                    return jsonify({'status': 'error', 'message': 'Recurring expense not found'}), 404
                category_id = result[0]
        
        # Capture old name before updating (for CA sync)
        old_expense_name = None
        cached_categories = _get_categories_from_redis('expense_categories', user_id)
        if cached_categories:
            for cat in cached_categories:
                if int(cat.get('id')) == int(category_id):
                    old_expense_name = cat.get('name')
                    break
        if not old_expense_name:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("SELECT name FROM expense_categories WHERE id = %s", (category_id,))
                row = cursor.fetchone()
                cursor.close()
                if row:
                    old_expense_name = row[0]

        # Step 2: Update the category name/flags in Redis (Redis-first)
        _update_category_in_redis('expense_categories', user_id, category_id, {
            'name': category_name,
            'is_recurring': 1,
            'no_end_date': no_end_date
        })

        # Convert the monthly_days array into a comma-separated string for storage, if it exists
        monthly_days_str = ','.join(map(str, monthly_days)) if monthly_days else None

        # Step 2b: Update the recurring expense record in Redis
        recurring_data = {
            'id': recurring_id,
            'user_id': user_id,
            'category_id': category_id,
            'category_name': category_name,  # Include the category name
            'amount': float(amount),
            'cadence_interval': cadence_interval,
            'cadence_unit': cadence_unit,
            'weekdays': ','.join(weekdays) if weekdays else None,
            'monthly_days': monthly_days_str,
            'yearly_day': yearly_day if yearly_day else None,
            'yearly_month': yearly_month if yearly_month else None,
            'start_date': start_date,
            'end_date': end_date,
            'no_end_date': no_end_date,
            'wage_bill': wage_bill
        }
        
        _update_recurring_in_redis('recurring_expense', user_id, recurring_data)

        # Step 3: Delete old expense entries for today and the future from Redis
        _delete_entry_in_redis('expense_entries', user_id, category_id, today, date(9999, 12, 31))
        
        # Step 3a: If this is a payment category, also delete future c_payment_entries (will be recreated below)
        payment_account_id = None
        categories_for_payment = _get_categories_from_redis('expense_categories', user_id)
        if categories_for_payment:
            cat = next((c for c in categories_for_payment if int(c.get('id', 0)) == int(category_id)), None)
            if cat and cat.get('is_credit_account') == 1 and cat.get('credit_account_id'):
                payment_account_id = int(cat['credit_account_id'])
        if payment_account_id:
            _delete_payment_entry_in_redis(user_id, payment_account_id, today, date(9999, 12, 31))
        
        # Step 3b: Delete future bucket records for this category
        _delete_future_buckets_in_redis('recurring_expense_buckets', user_id, category_id, today)

        # Step 3c: Sync rename to credit account categories if name changed
        if old_expense_name and old_expense_name != category_name:
            _sync_rename_to_credit_accounts(user_id, old_expense_name, category_name)
        
        # Step 4: Recreate the expense entries with the updated details (only for today and future)
        # Now writes to Redis, so works with both temp (negative) and real (positive) IDs
        if recurring_id:
            generate_expense_entries(recurring_id, category_id, amount, cadence_interval, cadence_unit, 
                                    start_date, end_date, weekdays, monthly_days, yearly_day, yearly_month)
        
        
        # Recalculate credit account balances if payment entries were modified
        if payment_account_id:
            save_ca_daily_balance()
        
        # Re-evaluate mismatch: auto-delete if user is manually editing
        try:
            from redis_crud import delete_recurring_mismatch
            delete_recurring_mismatch('recurring_expense', recurring_id, user_id=user_id)
        except Exception:
            pass
        
        return jsonify({'status': 'success', 'message': 'Recurring expense updated successfully!'})

    except Exception as e:
        return jsonify({'status': 'error', 'message': f'An error occurred: {str(e)}'}), 500

def get_cadence_description(cadence_interval, cadence_unit, weekdays=None, monthly_days=None, yearly_day=None, yearly_month=None):
    # Mapping for custom weekday abbreviations
    custom_weekday_abbreviations = {
        'monday': 'M',
        'tuesday': 'T',
        'wednesday': 'W',
        'thursday': 'Th',
        'friday': 'F',
        'saturday': 'S',
        'sunday': 'Su'
    }

    if cadence_unit == 'days':
        return f"Every {cadence_interval} day(s)"
    
    elif cadence_unit == 'weeks':
        if weekdays:
            # If weekdays is a string, split it into a list
            if isinstance(weekdays, str):
                weekdays = weekdays.split(',')

            # Ensure only valid weekdays are included and skip None/empty values
            valid_weekdays = [day.strip() for day in weekdays if day.strip().lower() in custom_weekday_abbreviations]
            
            if valid_weekdays:
                weekdays_str = ', '.join([custom_weekday_abbreviations[day.lower()] for day in valid_weekdays])
                return f"Every {cadence_interval} week(s) on {weekdays_str}"
            else:
                return f"Every {cadence_interval} week(s)"  # No valid weekdays to display
        else:
            return f"Every {cadence_interval} week(s)"
    
    elif cadence_unit == 'months':
        if monthly_days:
            # Clean the monthly_days list by splitting if it's a string
            if isinstance(monthly_days, str):
                monthly_days = [day.strip() for day in monthly_days.split(',') if day.strip()]

            # Remove duplicates and sort the days numerically
            monthly_days_cleaned = sorted(set(monthly_days), key=lambda x: int(x) if x.isdigit() else float('inf'))

            if monthly_days_cleaned:
                monthly_days_str = ', '.join(monthly_days_cleaned)
                return f"Every {cadence_interval} month(s) on days {monthly_days_str}"
            else:
                return f"Every {cadence_interval} month(s)"  # No valid monthly days
        else:
            return f"Every {cadence_interval} month(s)"
    
    elif cadence_unit == 'years':
        if yearly_day and yearly_month:
            # Get the month name based on the integer month
            month_name = calendar.month_name[int(yearly_month)]
            return f"Every {cadence_interval} year(s) on {month_name} {yearly_day}"
        else:
            return f"Every {cadence_interval} year(s)"

    # Fallback for unexpected or custom cadence cases
    return f"Custom Cadence: every {cadence_interval} {cadence_unit}(s)"

